insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('fa000000-0000-0000-0000-000000000001', 'mrcp1', '77fe7728-0d96-497b-af3a-bfc3f22f6ff6',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('fa000000-0000-0000-0000-000000000001', 'A', 'Start IV N-acetylcysteine if her plasma paracetamol level falls above the treatment line on the nomogram', true, 'Correct. For a paracetamol overdose presenting within 4-24 hours of a single acute ingestion, a plasma paracetamol level taken at least 4 hours post-ingestion should be plotted against time on the treatment nomogram; IV N-acetylcysteine is started if the level falls on or above the treatment line, replenishing hepatic glutathione stores to detoxify the toxic NAPQI metabolite and prevent hepatotoxicity.', 1),
('fa000000-0000-0000-0000-000000000001', 'B', 'Activated charcoal alone, with no other treatment regardless of the level', false, 'Ruled out because although activated charcoal can be considered within 1 hour of ingestion, at 5 hours post-ingestion its benefit is much reduced, and the definitive treatment decision (N-acetylcysteine) should be based on the timed paracetamol level and nomogram, not charcoal alone.', 2),
('fa000000-0000-0000-0000-000000000001', 'C', 'No treatment is needed, as she is currently asymptomatic', false, 'Ruled out because significant paracetamol overdose can cause severe, delayed hepatotoxicity despite initial absence of symptoms; treatment decisions are based on the paracetamol level relative to the nomogram, not current symptom status.', 3),
('fa000000-0000-0000-0000-000000000001', 'D', 'Immediate liver transplantation assessment regardless of paracetamol level', false, 'Ruled out because transplant assessment is reserved for cases of established, severe liver failure meeting specific criteria, not as an initial response to a single acute overdose before treatment and monitoring for hepatotoxicity.', 4),
('fa000000-0000-0000-0000-000000000001', 'E', 'Gastric lavage as the definitive treatment', false, 'Ruled out because gastric lavage is not standard management for paracetamol overdose at this time point, and even where used for other poisonings, it is not the definitive treatment; N-acetylcysteine guided by the nomogram is the appropriate approach here.', 5),
('fa000000-0000-0000-0000-000000000002', 'A', 'Withhold N-acetylcysteine, as it is only useful within 24 hours of ingestion', false, 'Ruled out because N-acetylcysteine still provides benefit beyond 24 hours in patients with evidence of hepatotoxicity or liver failure, and should not be withheld in this scenario.', 1),
('fa000000-0000-0000-0000-000000000002', 'B', $x$Start IV N-acetylcysteine immediately, and assess against King's College Hospital criteria for potential liver transplantation$x$, true, $x$Correct. In a late-presenting paracetamol overdose with evidence of significant hepatotoxicity (markedly raised ALT, coagulopathy, acidosis, renal impairment), N-acetylcysteine should be started immediately regardless of paracetamol level or nomogram timing, and the patient should be assessed against King's College Hospital criteria (which include arterial pH, INR, creatinine and encephalopathy grade) to identify those who may need urgent liver transplantation referral.$x$, 2),
('fa000000-0000-0000-0000-000000000002', 'C', 'Discharge with outpatient follow-up, as this is now too late for any effective treatment', false, 'Ruled out because this represents severe, evolving liver failure requiring urgent inpatient management, N-acetylcysteine, and assessment for transplantation, not discharge.', 3),
('fa000000-0000-0000-0000-000000000002', 'D', 'Perform gastric lavage as the priority intervention at this stage', false, 'Ruled out because gastric lavage has no role this many hours post-ingestion; the priority is N-acetylcysteine and assessment of liver failure severity.', 4),
('fa000000-0000-0000-0000-000000000002', 'E', 'Await a paracetamol level and nomogram interpretation before starting any treatment', false, 'Ruled out because with this degree of established hepatotoxicity, treatment should not be delayed pending a level/nomogram interpretation, which is not reliably interpretable this late after an unquantified ingestion time; treatment should start immediately on clinical and biochemical grounds.', 5),
('fa000000-0000-0000-0000-000000000003', 'A', 'Administer flumazenil', false, 'Ruled out because flumazenil reverses benzodiazepine, not opioid, toxicity; it would not address this presentation, which is characteristic of opioid overdose.', 1),
('fa000000-0000-0000-0000-000000000003', 'B', 'Administer activated charcoal as the primary treatment', false, 'Ruled out because activated charcoal does not address the immediate, life-threatening respiratory depression, which requires prompt reversal with naloxone; charcoal has limited relevant role in this acute emergency.', 2),
('fa000000-0000-0000-0000-000000000003', 'C', 'Administer naloxone and provide ventilatory support, with awareness that repeated doses or an infusion may be needed given his modified-release formulation', true, $x$Correct. Pinpoint pupils and severe respiratory depression indicate opioid toxicity; naloxone (an opioid receptor antagonist) should be given promptly alongside airway/ventilatory support, with close monitoring and repeat dosing or an infusion likely required given naloxone's shorter half-life compared with the long-acting modified-release opioid, to prevent recurrent respiratory depression as the naloxone effect wears off.$x$, 3),
('fa000000-0000-0000-0000-000000000003', 'D', 'Observe without active intervention, as this will likely self-resolve', false, 'Ruled out because this represents a life-threatening emergency (severe respiratory depression) requiring immediate active reversal with naloxone, not passive observation.', 4),
('fa000000-0000-0000-0000-000000000003', 'E', 'Give high-flow oxygen alone, without naloxone', false, 'Ruled out because although supporting oxygenation is important, naloxone specifically reverses the underlying opioid-induced respiratory depression and should be given promptly alongside airway/ventilatory support, not omitted.', 5),
('fa000000-0000-0000-0000-000000000004', 'A', 'IV flumazenil', false, 'Ruled out because flumazenil reverses benzodiazepine toxicity, not tricyclic antidepressant cardiotoxicity, and can precipitate seizures in mixed overdoses; it is not the appropriate treatment here.', 1),
('fa000000-0000-0000-0000-000000000004', 'B', 'IV naloxone', false, 'Ruled out because naloxone reverses opioid toxicity, not tricyclic antidepressant cardiotoxicity, which requires sodium bicarbonate.', 2),
('fa000000-0000-0000-0000-000000000004', 'C', 'Standard anti-arrhythmic drugs such as flecainide', false, 'Ruled out because class Ia and Ic anti-arrhythmics share a similar sodium-channel blocking mechanism to tricyclics and can worsen, not improve, TCA-induced cardiotoxicity; they are specifically avoided in this context.', 3),
('fa000000-0000-0000-0000-000000000004', 'D', 'Activated charcoal alone, with no specific cardiac treatment', false, 'Ruled out because although activated charcoal may have a role if given early, it does not address the current cardiotoxicity requiring specific, immediate treatment with sodium bicarbonate.', 4),
('fa000000-0000-0000-0000-000000000004', 'E', 'IV sodium bicarbonate', true, $x$Correct. QRS widening in tricyclic antidepressant overdose reflects sodium channel blockade in cardiac myocytes; IV sodium bicarbonate is the specific treatment, working by increasing extracellular sodium concentration (overcoming the blockade) and alkalinising the blood (reducing the drug's binding affinity to cardiac sodium channels), improving cardiac conduction and reducing arrhythmia risk.$x$, 5),
('fa000000-0000-0000-0000-000000000005', 'A', 'Serum digoxin level', false, 'Ruled out because there is no indication he is taking digoxin; the clinical picture and clear precipitants for reduced renal clearance point specifically to lithium toxicity, requiring a lithium level.', 1),
('fa000000-0000-0000-0000-000000000005', 'B', 'Serum paracetamol level', false, 'Ruled out because there is no suggestion of paracetamol ingestion; his presentation and background are specific to lithium toxicity.', 2),
('fa000000-0000-0000-0000-000000000005', 'C', 'Urine toxicology screen for illicit drugs', false, 'Ruled out because his presentation is well explained by lithium toxicity precipitated by identified drug interaction and dehydration, making a lithium level the appropriate, targeted investigation rather than a broad illicit drug screen.', 3),
('fa000000-0000-0000-0000-000000000005', 'D', 'Urgent serum lithium level', true, 'Correct. Confusion, coarse tremor, ataxia and vomiting in a patient on lithium, with a clear precipitant for reduced lithium clearance (ACE inhibitor use and dehydration from diarrhoeal illness, both reducing renal lithium excretion), is characteristic of lithium toxicity; an urgent serum lithium level confirms the diagnosis and guides further management, which may include IV fluids and, in severe cases, haemodialysis.', 4),
('fa000000-0000-0000-0000-000000000005', 'E', 'No specific investigation is needed; management should proceed empirically', false, 'Ruled out because confirming the serum lithium level is important both to confirm the diagnosis and to guide the intensity of treatment (including the threshold for considering dialysis in severe toxicity).', 5),
('fa000000-0000-0000-0000-000000000006', 'A', $x$Further beta-blocker administration to 'out-compete' the overdose$x$, false, 'Ruled out because this is illogical and would worsen, not improve, his beta-blocker toxicity.', 1),
('fa000000-0000-0000-0000-000000000006', 'B', 'IV adrenaline as first-line treatment', false, $x$Ruled out because adrenaline's effect is significantly blunted by ongoing beta-receptor blockade, making it a less specific and less reliably effective first-line choice than glucagon in significant beta-blocker toxicity, though it and other measures may be used in refractory cases alongside glucagon.$x$, 2),
('fa000000-0000-0000-0000-000000000006', 'C', 'Activated charcoal alone, with no specific cardiovascular treatment', false, 'Ruled out because although activated charcoal may have a role if given very early, it does not address his current significant bradycardia and hypotension, which require specific treatment with glucagon.', 3),
('fa000000-0000-0000-0000-000000000006', 'D', 'Immediate cardioversion', false, 'Ruled out because cardioversion is used for tachyarrhythmias, not the bradycardia and hypotension caused by beta-blocker toxicity; glucagon is the specific pharmacological treatment indicated here.', 4),
('fa000000-0000-0000-0000-000000000006', 'E', 'IV glucagon', true, 'Correct. Glucagon is the specific antidote for severe beta-blocker toxicity, bypassing the blocked beta-adrenergic receptor by directly stimulating cardiac adenylate cyclase through a separate receptor pathway, increasing intracellular cyclic AMP and improving heart rate and contractility independent of beta-receptor blockade.', 5),
('fa000000-0000-0000-0000-000000000007', 'A', 'Oral glucose gel, as she is conscious', false, 'Ruled out because although conscious, her disorientation and inability to safely swallow create a significant aspiration risk with oral treatment; parenteral treatment (IM glucagon or IV glucose) is the appropriate choice in this context.', 1),
('fa000000-0000-0000-0000-000000000007', 'B', 'Insulin, to help stabilise her blood glucose', false, 'Ruled out because giving insulin during hypoglycaemia would dangerously worsen her already low blood glucose.', 2),
('fa000000-0000-0000-0000-000000000007', 'C', 'No treatment; reassess in one hour', false, 'Ruled out because severe hypoglycaemia is a medical emergency requiring prompt treatment, not delayed reassessment, given the risk of seizure or worsening neuroglycopenia.', 3),
('fa000000-0000-0000-0000-000000000007', 'D', 'IM glucagon (or IV glucose if IV access is readily available), given her inability to safely take oral treatment', true, 'Correct. Severe hypoglycaemia with reduced ability to safely swallow requires parenteral treatment rather than oral glucose (which risks aspiration); IM glucagon (stimulating hepatic glycogenolysis) is appropriate if IV access is not readily available, or IV glucose can be given directly if access is already established, followed by reassessment and oral carbohydrate once she is able to swallow safely.', 4),
('fa000000-0000-0000-0000-000000000007', 'E', 'IV insulin infusion to manage her diabetes more tightly going forward', false, 'Ruled out because this is the opposite of what is needed acutely; the immediate priority is correcting her current severe hypoglycaemia, not initiating further insulin therapy.', 5),
('fa000000-0000-0000-0000-000000000008', 'A', 'Activated charcoal, given the recent timing, alongside supportive care and monitoring of salicylate levels and acid-base status', true, 'Correct. Although the stem describes an NSAID (ibuprofen) overdose, tinnitus with a mixed respiratory alkalosis/metabolic acidosis picture is classically associated with salicylate toxicity, and the general principles (activated charcoal within an appropriate time window given the acute large ingestion, supportive care, and monitoring salicylate/paracetamol levels and acid-base status, with consideration of urinary alkalinisation or haemodialysis in more severe salicylate poisoning) apply to significant analgesic overdose presentations of this type.', 1),
('fa000000-0000-0000-0000-000000000008', 'B', 'No treatment is required, as ibuprofen overdose is never significant', false, 'Ruled out because a large, intentional NSAID overdose can cause significant toxicity (gastrointestinal, renal, and in salicylate-type toxicity, acid-base disturbance) and requires assessment and appropriate management, not being dismissed as insignificant.', 2),
('fa000000-0000-0000-0000-000000000008', 'C', 'Immediate haemodialysis for all NSAID overdoses regardless of severity', false, 'Ruled out because haemodialysis is reserved for severe, specific toxicity (e.g. severe salicylate poisoning with marked acidosis or very high levels), not applied routinely to all NSAID overdoses regardless of severity.', 3),
('fa000000-0000-0000-0000-000000000008', 'D', 'N-acetylcysteine as the primary treatment', false, 'Ruled out because N-acetylcysteine is the specific antidote for paracetamol toxicity, not for NSAID/salicylate-type overdose; it would not address this presentation unless paracetamol co-ingestion were also confirmed.', 4),
('fa000000-0000-0000-0000-000000000008', 'E', 'Naloxone as the primary treatment', false, 'Ruled out because naloxone reverses opioid toxicity, not NSAID/salicylate overdose, and would not be expected to have any effect on this presentation.', 5),
('fa000000-0000-0000-0000-000000000009', 'A', 'N-acetylcysteine as the specific antidote', false, 'Ruled out because N-acetylcysteine is the specific antidote for paracetamol toxicity, not ethylene glycol poisoning, which requires alcohol dehydrogenase inhibition instead.', 1),
('fa000000-0000-0000-0000-000000000009', 'B', 'Naloxone as the specific antidote', false, 'Ruled out because naloxone reverses opioid toxicity, unrelated to the mechanism of ethylene glycol poisoning.', 2),
('fa000000-0000-0000-0000-000000000009', 'C', 'Fomepizole (or, if unavailable, ethanol) to inhibit alcohol dehydrogenase', true, 'Correct. Ethylene glycol (a component of antifreeze) is metabolised by alcohol dehydrogenase into toxic metabolites (including glycolic and oxalic acid) responsible for the severe metabolic acidosis and end-organ toxicity (including visual disturbance from methanol-related toxicity in similar poisonings, and renal toxicity from oxalate crystal deposition in ethylene glycol poisoning specifically); fomepizole competitively inhibits alcohol dehydrogenase, preventing further toxic metabolite formation, with ethanol as an alternative if fomepizole is unavailable.', 3),
('fa000000-0000-0000-0000-000000000009', 'D', 'Immediate administration of more ethanol-containing alcoholic drinks with no medical supervision', false, 'Ruled out because although ethanol can be used therapeutically to competitively inhibit alcohol dehydrogenase, this must be done as a carefully monitored medical treatment (IV ethanol or fomepizole), not through unsupervised alcoholic drink consumption.', 4),
('fa000000-0000-0000-0000-000000000009', 'E', 'Activated charcoal as the definitive treatment', false, 'Ruled out because activated charcoal does not effectively adsorb ethylene glycol and is not the definitive treatment; alcohol dehydrogenase inhibition (fomepizole or ethanol) is the specific antidote required.', 5),
('fa000000-0000-0000-0000-000000000010', 'A', 'Continue warfarin at the same dose, as there is no active bleeding', false, 'Ruled out because an INR this high carries a significant bleeding risk even without current bleeding, and specific action (withholding warfarin, vitamin K) is indicated rather than continuing unchanged treatment.', 1),
('fa000000-0000-0000-0000-000000000010', 'B', 'Stop warfarin and give oral vitamin K, with INR rechecked the following day', true, 'Correct. A markedly elevated INR (typically above 8) without active bleeding is managed by withholding warfarin and giving oral vitamin K to help reduce the INR into a safer range, with INR rechecked the next day and warfarin restarted at a lower dose once the INR falls to a safer level.', 2),
('fa000000-0000-0000-0000-000000000010', 'C', 'Give IV prothrombin complex concentrate', false, 'Ruled out because PCC is reserved for major or life-threatening bleeding requiring rapid reversal; for this markedly elevated but asymptomatic INR without active bleeding, oral vitamin K and warfarin cessation is the appropriate, less aggressive approach.', 3),
('fa000000-0000-0000-0000-000000000010', 'D', $x$Double the warfarin dose to 'catch up' on missed anticoagulation$x$, false, 'Ruled out because this is the opposite of the appropriate response; his INR is already dangerously high, and increasing the dose would further worsen over-anticoagulation and bleeding risk.', 4),
('fa000000-0000-0000-0000-000000000010', 'E', 'No action needed until his next scheduled INR check in four weeks', false, 'Ruled out because an INR of 8.2 requires prompt action (withholding warfarin, vitamin K, and a sooner recheck) rather than waiting until the next routine scheduled appointment.', 5),
('fa000000-0000-0000-0000-000000000011', 'A', 'Oral vitamin K alone, without prothrombin complex concentrate', false, 'Ruled out because oral vitamin K acts too slowly for this life-threatening major bleeding scenario; PCC is needed for immediate factor replacement, combined with vitamin K for more sustained effect.', 1),
('fa000000-0000-0000-0000-000000000011', 'B', 'Withholding warfarin alone with no active reversal agent given', false, 'Ruled out because simply withholding warfarin does not provide rapid enough correction for major, life-threatening bleeding; active reversal with vitamin K and PCC is required.', 2),
('fa000000-0000-0000-0000-000000000011', 'C', 'IV vitamin K and prothrombin complex concentrate', true, 'Correct. Major, life-threatening bleeding on warfarin requires immediate reversal with IV vitamin K (to restore synthesis of vitamin K-dependent clotting factors over subsequent hours) combined with prothrombin complex concentrate (providing immediate replacement of factors II, VII, IX and X), providing the most rapid and complete correction of the coagulopathy.', 3),
('fa000000-0000-0000-0000-000000000011', 'D', 'Fresh frozen plasma as the definitive first-line reversal agent in preference to PCC', false, 'Ruled out because PCC is preferred over FFP for warfarin reversal in major bleeding, given its more concentrated, rapid and reliable correction of the specific deficient factors, with a smaller required infusion volume.', 4),
('fa000000-0000-0000-0000-000000000011', 'E', 'Protamine sulfate', false, 'Ruled out because protamine sulfate reverses heparin, not warfarin; it has no role in reversing vitamin K antagonist-related coagulopathy.', 5),
('fa000000-0000-0000-0000-000000000012', 'A', 'Idarucizumab', false, 'Ruled out because idarucizumab is the specific reversal agent for dabigatran (a direct thrombin inhibitor), not for factor Xa inhibitors such as rivaroxaban.', 1),
('fa000000-0000-0000-0000-000000000012', 'B', 'Protamine sulfate', false, 'Ruled out because protamine sulfate reverses heparin, not direct oral factor Xa inhibitors like rivaroxaban.', 2),
('fa000000-0000-0000-0000-000000000012', 'C', 'Vitamin K', false, 'Ruled out because vitamin K reverses vitamin K antagonists (warfarin), not direct oral anticoagulants such as rivaroxaban, which work through a different, vitamin K-independent mechanism.', 3),
('fa000000-0000-0000-0000-000000000012', 'D', 'Andexanet alfa (a specific factor Xa inhibitor reversal agent), or prothrombin complex concentrate if unavailable', true, 'Correct. Andexanet alfa is a specific reversal agent for factor Xa inhibitors (such as rivaroxaban and apixaban), acting as a decoy molecule that binds the drug and restores normal factor Xa activity; where andexanet alfa is unavailable, prothrombin complex concentrate is used as an alternative, less specific but still clinically useful option in this emergency setting.', 4),
('fa000000-0000-0000-0000-000000000012', 'E', 'No reversal agent exists for any direct oral anticoagulant', false, 'Ruled out because specific reversal agents do exist for both major classes of DOACs (idarucizumab for dabigatral, andexanet alfa for factor Xa inhibitors), directly contradicting this statement.', 5),
('fa000000-0000-0000-0000-000000000013', 'A', 'Idarucizumab', true, 'Correct. Idarucizumab is a specific monoclonal antibody fragment that binds dabigatran with high affinity, rapidly and completely reversing its anticoagulant effect, making it the appropriate specific reversal agent for this direct thrombin inhibitor in the context of life-threatening bleeding requiring urgent intervention.', 1),
('fa000000-0000-0000-0000-000000000013', 'B', 'Andexanet alfa', false, 'Ruled out because andexanet alfa is the specific reversal agent for factor Xa inhibitors (rivaroxaban, apixaban), not for dabigatran, which works via direct thrombin inhibition and requires idarucizumab instead.', 2),
('fa000000-0000-0000-0000-000000000013', 'C', 'Protamine sulfate', false, 'Ruled out because protamine sulfate reverses heparin, not dabigatran.', 3),
('fa000000-0000-0000-0000-000000000013', 'D', 'Vitamin K', false, 'Ruled out because vitamin K reverses vitamin K antagonists (warfarin), not direct thrombin inhibitors such as dabigatran.', 4),
('fa000000-0000-0000-0000-000000000013', 'E', 'Fresh frozen plasma as the specific reversal agent of choice', false, 'Ruled out because FFP is not the specific, targeted reversal agent for dabigatran; idarucizumab, with its specific high-affinity binding mechanism, is the appropriate choice when available for this emergency.', 5),
('fa000000-0000-0000-0000-000000000014', 'A', 'They work through an identical mechanism, and combining them simply doubles the effect of a single pathway', false, 'Ruled out because aspirin and P2Y12 inhibitors act through distinct pharmacological mechanisms, not the same pathway; their combined benefit specifically comes from targeting complementary platelet activation pathways.', 1),
('fa000000-0000-0000-0000-000000000014', 'B', 'They act through complementary, distinct mechanisms of platelet inhibition, providing more effective prevention of stent thrombosis than either agent alone', true, 'Correct. Aspirin inhibits platelet cyclooxygenase (reducing thromboxane A2-mediated platelet activation), while P2Y12 inhibitors (e.g. clopidogrel, ticagrelor) block a separate ADP receptor pathway; combining these complementary mechanisms provides more effective platelet inhibition than either drug alone, significantly reducing the risk of stent thrombosis, a serious complication following stent insertion, particularly important during the period of stent endothelialisation.', 2),
('fa000000-0000-0000-0000-000000000014', 'C', 'Dual therapy is used purely for cost reasons rather than any pharmacological rationale', false, 'Ruled out because the combination is based on genuine, evidence-based pharmacological synergy in reducing stent thrombosis risk, not a cost-driven decision.', 3),
('fa000000-0000-0000-0000-000000000014', 'D', 'Combining them has no proven additional benefit over aspirin alone after stenting', false, 'Ruled out because dual antiplatelet therapy has robust evidence demonstrating significantly reduced stent thrombosis risk compared with aspirin monotherapy following stent insertion, particularly with drug-eluting stents.', 4),
('fa000000-0000-0000-0000-000000000014', 'E', 'The combination is used specifically to reduce bleeding risk compared with either drug alone', false, 'Ruled out because dual antiplatelet therapy actually increases bleeding risk compared with either single agent; the rationale for its use is the significant reduction in stent thrombosis risk, which is judged to outweigh this increased bleeding risk during the relevant treatment period.', 5),
('fa000000-0000-0000-0000-000000000015', 'A', 'Unfractionated heparin requires monitoring because it has no therapeutic effect without dose titration based on APTT', false, 'Ruled out because unfractionated heparin does have anticoagulant effect at any given dose; the issue is the unpredictability of that effect between individuals, which is why titration against a target APTT range is needed to ensure it falls within an effective and safe range.', 1),
('fa000000-0000-0000-0000-000000000015', 'B', 'APTT monitoring is done purely as a legal requirement with no clinical basis', false, 'Ruled out because APTT monitoring has a genuine clinical basis (ensuring adequate, safe anticoagulation given the unpredictable dose-response), not simply being a procedural or legal formality.', 2),
('fa000000-0000-0000-0000-000000000015', 'C', 'Low molecular weight heparin requires the same intensity of monitoring as unfractionated heparin', false, 'Ruled out because LMWH has a more predictable dose-response, generally allowing weight-based dosing without routine anti-Xa or APTT monitoring in most patients, unlike unfractionated heparin.', 3),
('fa000000-0000-0000-0000-000000000015', 'D', 'APTT monitoring is used to detect heparin-induced thrombocytopenia', false, 'Ruled out because heparin-induced thrombocytopenia is monitored via platelet count trends, not APTT; APTT monitoring specifically relates to titrating the anticoagulant dose to a therapeutic range.', 4),
('fa000000-0000-0000-0000-000000000015', 'E', 'Unfractionated heparin has a relatively unpredictable dose-response relationship, requiring regular APTT monitoring to ensure adequate but safe anticoagulation', true, $x$Correct. Unlike low molecular weight heparin (which has a more predictable dose-response allowing weight-based dosing without routine monitoring in most patients), unfractionated heparin's anticoagulant effect varies significantly between individuals due to variable binding to plasma proteins and other factors, necessitating regular APTT monitoring to titrate the dose within a therapeutic range, avoiding under- or over-anticoagulation.$x$, 5),
('fa000000-0000-0000-0000-000000000016', 'A', 'Simple bone marrow suppression from a direct toxic drug effect', false, 'Ruled out because the specific, clinically important complication being monitored for is heparin-induced thrombocytopenia, an immune-mediated (not simple direct toxic marrow suppression) mechanism with a distinct, paradoxical thrombotic risk.', 1),
('fa000000-0000-0000-0000-000000000016', 'B', 'Heparin-induced thrombocytopenia', true, 'Correct. Regular platelet count monitoring during heparin therapy (both unfractionated and, less commonly, low molecular weight heparin) is specifically designed to detect heparin-induced thrombocytopenia, an immune-mediated reaction typically developing 5-10 days after starting heparin, which paradoxically increases thrombotic risk despite the falling platelet count, requiring immediate heparin cessation and switch to a non-heparin anticoagulant if identified.', 2),
('fa000000-0000-0000-0000-000000000016', 'C', 'Vitamin K deficiency', false, 'Ruled out because vitamin K deficiency is unrelated to heparin therapy and platelet count monitoring; it would affect the vitamin K-dependent clotting factors, not platelet count specifically in this context.', 3),
('fa000000-0000-0000-0000-000000000016', 'D', 'Warfarin-induced skin necrosis', false, 'Ruled out because this is a specific complication of warfarin (related to transient protein C deficiency early in treatment), not heparin, and is not detected by platelet count monitoring.', 4),
('fa000000-0000-0000-0000-000000000016', 'E', 'Disseminated intravascular coagulation caused directly by heparin itself', false, 'Ruled out because heparin therapy itself does not directly cause DIC; the specific complication being monitored for with platelet counts during heparin treatment is heparin-induced thrombocytopenia.', 5),
('fa000000-0000-0000-0000-000000000017', 'A', 'A high bleeding risk score is an absolute contraindication to any anticoagulation, regardless of stroke risk', false, 'Ruled out because a high bleeding risk score alone does not automatically contraindicate anticoagulation; it should prompt risk factor modification and careful individualised balancing against stroke risk, not automatic exclusion from treatment.', 1),
('fa000000-0000-0000-0000-000000000017', 'B', 'Bleeding risk scores and stroke risk scores are used interchangeably and measure the same underlying risk', false, 'Ruled out because these are distinct, separate risk assessments (bleeding risk versus thromboembolic/stroke risk) that are considered together, not interchangeable measures of the same risk.', 2),
('fa000000-0000-0000-0000-000000000017', 'C', 'Falls risk alone, regardless of frequency or severity, is always an absolute contraindication to anticoagulation', false, 'Ruled out because falls risk is one factor to consider and, where possible, address (e.g. falls prevention interventions), but is not by itself an automatic, absolute contraindication to anticoagulation in a patient with significant stroke risk, given that the risk of a major bleed from a fall is often lower than the stroke risk reduction benefit of anticoagulation in appropriately selected patients.', 3),
('fa000000-0000-0000-0000-000000000017', 'D', 'A high bleeding risk score should prompt identification and correction of modifiable risk factors and closer monitoring, rather than being used alone to withhold anticoagulation when stroke risk is also significant', true, 'Correct. Bleeding risk scores (such as HAS-BLED) are intended to identify and address modifiable bleeding risk factors (e.g. blood pressure control, concurrent antiplatelet/NSAID use, falls risk assessment) and guide closer monitoring, rather than being used in isolation to withhold anticoagulation; the decision to anticoagulate should balance bleeding risk against stroke risk (e.g. via CHA2DS2-VASc), as stroke prevention benefit often still outweighs bleeding risk even in higher-risk patients, particularly with careful risk factor modification and monitoring.', 4),
('fa000000-0000-0000-0000-000000000017', 'E', 'Bleeding risk scores are not validated tools and should not be used in clinical practice', false, 'Ruled out because bleeding risk assessment tools such as HAS-BLED are validated, evidence-based tools used specifically to identify modifiable risk factors and inform shared decision-making, not tools without a clinical evidence base.', 5),
('fa000000-0000-0000-0000-000000000018', 'A', 'Metformin should not be started, given her eGFR is below the threshold at which it is contraindicated due to lactic acidosis risk', true, 'Correct. Metformin is contraindicated at an eGFR below 30 mL/min/1.73m2 due to the risk of lactic acidosis from reduced renal clearance and accumulation; at 22 mL/min/1.73m2, metformin should not be started, and an alternative glucose-lowering agent appropriate for this level of renal impairment should be considered instead.', 1),
('fa000000-0000-0000-0000-000000000018', 'B', 'Metformin can be started at the standard full dose with no specific renal consideration', false, 'Ruled out because standard-dose metformin at this level of renal impairment carries a significant lactic acidosis risk; it should not be started at this eGFR.', 2),
('fa000000-0000-0000-0000-000000000018', 'C', 'Metformin should be started but at double the standard dose to overcome reduced efficacy', false, 'Ruled out because increasing the dose would further increase, not reduce, the accumulation and lactic acidosis risk; this eGFR level means metformin should not be started at all, not started at a higher dose.', 3),
('fa000000-0000-0000-0000-000000000018', 'D', 'Metformin dose should simply be halved and then used long-term without further monitoring', false, 'Ruled out because at this eGFR (below 30), metformin is contraindicated altogether, not simply requiring a dose reduction as might apply at a higher eGFR range (30-45).', 4),
('fa000000-0000-0000-0000-000000000018', 'E', 'Renal function has no bearing on metformin prescribing decisions', false, 'Ruled out because renal function is a critical, specific consideration for metformin prescribing, directly determining whether it can be used, and if so, at what dose.', 5),
('fa000000-0000-0000-0000-000000000019', 'A', 'No dose adjustment is needed regardless of his renal function', false, 'Ruled out because gentamicin would accumulate significantly if dosed without adjustment in this level of renal impairment, substantially increasing nephrotoxicity and ototoxicity risk.', 1),
('fa000000-0000-0000-0000-000000000019', 'B', 'Gentamicin should be given as a fixed standard dose without any monitoring', false, $x$Ruled out because gentamicin's narrow therapeutic index necessitates level monitoring, particularly important in the context of significant renal impairment, to avoid toxicity while ensuring adequate treatment.$x$, 2),
('fa000000-0000-0000-0000-000000000019', 'C', 'Gentamicin dose and/or dosing interval must be adjusted based on his renal function, with close therapeutic drug level monitoring', true, 'Correct. Gentamicin is renally cleared and has a narrow therapeutic index with significant nephrotoxic and ototoxic potential; in significant renal impairment, the dose and/or dosing interval must be carefully adjusted based on renal function, with therapeutic drug monitoring used to guide safe, effective dosing and avoid further accumulation and toxicity.', 3),
('fa000000-0000-0000-0000-000000000019', 'D', 'The dose should be increased to compensate for his reduced renal function', false, 'Ruled out because reduced renal clearance means the drug will accumulate at standard or higher doses; the dose and/or interval should be reduced/extended, not increased, in this context.', 4),
('fa000000-0000-0000-0000-000000000019', 'E', 'Renal function is irrelevant to gentamicin dosing decisions', false, 'Ruled out because renal function is a critical, specific factor directly determining safe gentamicin dosing, given its renal clearance and narrow therapeutic index.', 5),
('fa000000-0000-0000-0000-000000000020', 'A', 'No dose adjustment or caution is needed regardless of the severity of his liver disease', false, 'Ruled out because significant hepatic impairment meaningfully alters the metabolism of many analgesics, making dose caution and careful titration important, not proceeding with standard, unadjusted dosing regardless of severity.', 1),
('fa000000-0000-0000-0000-000000000020', 'B', 'All analgesics should be completely avoided in any degree of liver disease', false, 'Ruled out because analgesics can still be used effectively and relatively safely in hepatic impairment with appropriate caution (lower starting doses, careful titration, monitoring); complete avoidance is not necessary or appropriate when analgesia is clinically needed.', 2),
('fa000000-0000-0000-0000-000000000020', 'C', 'Opioid doses should be increased to overcome reduced effectiveness in liver disease', false, 'Ruled out because this is the opposite of the appropriate approach; reduced hepatic metabolism increases toxicity risk at standard or higher doses, meaning lower, not higher, starting doses are appropriate in significant hepatic impairment.', 3),
('fa000000-0000-0000-0000-000000000020', 'D', 'Liver function has no relevance to analgesic prescribing decisions', false, 'Ruled out because liver function is a critical, specific consideration for analgesic prescribing, particularly for opioids, directly affecting dosing and monitoring decisions.', 4),
('fa000000-0000-0000-0000-000000000020', 'E', 'Both paracetamol and opioid analgesics require caution and, in the case of opioids, dose reduction with careful titration, given reduced hepatic metabolic capacity and increased sensitivity to sedative effects', true, $x$Correct. Significant hepatic impairment reduces the liver's capacity to metabolise many drugs, including opioids (increasing accumulation and sedation/respiratory depression risk, requiring lower starting doses and careful titration) and, to a lesser extent, paracetamol (where standard doses are generally still used with caution, though very high-risk or acute liver failure contexts require more caution); careful, individualised prescribing with specialist input is often valuable given this complexity.$x$, 5),
('fa000000-0000-0000-0000-000000000021', 'A', 'Apixaban is absolutely contraindicated at any degree of renal impairment', false, 'Ruled out because apixaban can generally still be used with appropriate dose adjustment down to more significant degrees of renal impairment than this, rather than being absolutely contraindicated here.', 1),
('fa000000-0000-0000-0000-000000000021', 'B', 'No dose adjustment or specific monitoring is needed regardless of renal function', false, $x$Ruled out because renal function is a specific, important consideration for apixaban dosing, and regular monitoring is recommended given the drug's partial renal clearance and the risk of further renal function decline affecting dosing appropriateness over time.$x$, 2),
('fa000000-0000-0000-0000-000000000021', 'C', 'Warfarin should always be used instead of any DOAC in patients with any degree of renal impairment', false, 'Ruled out because DOACs, including apixaban with appropriate dose adjustment, remain a suitable and often preferred option in many patients with renal impairment, rather than warfarin always being mandated instead.', 3),
('fa000000-0000-0000-0000-000000000021', 'D', 'Apixaban can generally still be used in this degree of renal impairment, but with dose adjustment according to the specific dose-reduction criteria for this drug, and regular renal function monitoring', true, 'Correct. Unlike some other DOACs, apixaban can generally still be used down to more significant degrees of renal impairment, but requires dose adjustment based on specific criteria (which for apixaban include age, weight and creatinine level, alongside renal function), with regular renal function monitoring given the risk of further deterioration affecting drug clearance and accumulation risk over time.', 4),
('fa000000-0000-0000-0000-000000000021', 'E', 'The apixaban dose should be increased in renal impairment to compensate for reduced absorption', false, 'Ruled out because renal impairment does not reduce apixaban absorption; rather, it can reduce clearance, meaning dose reduction (based on specific criteria), not an increase, is the relevant consideration.', 5),
('fa000000-0000-0000-0000-000000000022', 'A', 'Stop the NSAID, given the significant risk of worsening renal function, fluid retention and gastrointestinal bleeding in decompensated cirrhosis', true, 'Correct. NSAIDs are generally avoided in decompensated cirrhosis with ascites, as they can precipitate or worsen renal impairment (through reduced renal prostaglandin-mediated perfusion, particularly problematic alongside diuretics and in the context of cirrhosis-related circulatory changes), worsen fluid retention (counteracting diuretic therapy), and increase gastrointestinal bleeding risk (relevant given the risk of varices and coagulopathy in cirrhosis).', 1),
('fa000000-0000-0000-0000-000000000022', 'B', 'Continue the NSAID at the same dose, as it has no relevant interaction with his liver disease', false, 'Ruled out because NSAIDs carry specific, significant risks in decompensated cirrhosis (renal impairment, worsened fluid retention, GI bleeding risk), making continuation without action inappropriate.', 2),
('fa000000-0000-0000-0000-000000000022', 'C', 'Increase the NSAID dose to better control his joint pain', false, 'Ruled out because increasing the dose would further increase these significant risks, the opposite of the appropriate action in this context.', 3),
('fa000000-0000-0000-0000-000000000022', 'D', 'Add a proton pump inhibitor and continue the NSAID unchanged, with no further consideration', false, 'Ruled out because although a PPI may reduce some GI risk, it does not address the renal and fluid balance risks of NSAIDs in decompensated cirrhosis, which are the primary concern prompting NSAID avoidance in this context, not just the bleeding risk alone.', 4),
('fa000000-0000-0000-0000-000000000022', 'E', 'NSAIDs have no specific relevance to management decisions in liver disease', false, 'Ruled out because NSAID use is a specific, important prescribing consideration in decompensated cirrhosis given the several relevant risks described.', 5),
('fa000000-0000-0000-0000-000000000023', 'A', 'Statins are absolutely contraindicated in any degree of renal impairment', false, 'Ruled out because statins can generally still be used, often with dose consideration, in significant renal impairment; they are not absolutely contraindicated at this eGFR.', 1),
('fa000000-0000-0000-0000-000000000023', 'B', 'Statins can generally still be used in significant renal impairment, though some agents and doses require specific caution or adjustment, and cardiovascular risk reduction benefit is still considered relevant', true, 'Correct. Statins remain an important part of secondary cardiovascular prevention even in significant renal impairment, though specific agents and starting doses may need adjustment (some statins have specific renal dose caps or preferences in significant CKD), reflecting a balance between continued cardiovascular benefit and any specific renal-related dosing considerations for the chosen agent.', 2),
('fa000000-0000-0000-0000-000000000023', 'C', 'No dose consideration is needed regardless of the severity of renal impairment', false, 'Ruled out because some statins do have specific renal-related dosing considerations or caps at significant levels of impairment, making this an oversimplification, though the core message that statins remain usable is correct.', 3),
('fa000000-0000-0000-0000-000000000023', 'D', 'Statins provide no cardiovascular benefit in patients with chronic kidney disease and should be stopped', false, 'Ruled out because statins retain cardiovascular risk reduction benefit in many patients with CKD, particularly for secondary prevention following an established cardiovascular event, making stopping them inappropriate without specific indication to do so.', 4),
('fa000000-0000-0000-0000-000000000023', 'E', 'The statin dose should be increased in renal impairment to compensate for reduced absorption', false, 'Ruled out because renal impairment does not typically reduce statin absorption in this way; the relevant consideration is agent-specific dosing caution, not a need to increase the dose.', 5),
('fa000000-0000-0000-0000-000000000024', 'A', 'Continue the antihistamine unchanged, as it has no relevant interaction with his liver disease', false, 'Ruled out because sedating antihistamines carry a specific, recognised risk of worsening or precipitating hepatic encephalopathy in patients with significant liver disease, making continuation without action inappropriate.', 1),
('fa000000-0000-0000-0000-000000000024', 'B', 'Increase the antihistamine dose to better control his itching', false, 'Ruled out because increasing the dose would further increase sedation and encephalopathy risk, the opposite of the appropriate action in this clinically vulnerable context.', 2),
('fa000000-0000-0000-0000-000000000024', 'C', 'Sedating medications have no specific relevance to hepatic encephalopathy risk', false, $x$Ruled out because sedating medications are a specific, well-recognised risk factor for worsening or precipitating hepatic encephalopathy, directly relevant to this patient's care.$x$, 3),
('fa000000-0000-0000-0000-000000000024', 'D', 'Switch to an even more strongly sedating antihistamine for better itch control', false, 'Ruled out because this would further increase, not reduce, the encephalopathy risk; a non-sedating approach to itch management is preferred in this context.', 4),
('fa000000-0000-0000-0000-000000000024', 'E', 'Stop the sedating antihistamine, given the risk of worsening or precipitating hepatic encephalopathy', true, 'Correct. Sedating medications, including certain antihistamines, are generally avoided or used with great caution in patients with (or at risk of) hepatic encephalopathy, as their central sedative effects can worsen encephalopathy severity or precipitate an episode, particularly relevant in a patient with significant, decompensated liver disease and reduced hepatic drug clearance; alternative, non-sedating approaches to managing his cholestatic itch should be considered instead.', 5),
('fa000000-0000-0000-0000-000000000025', 'A', 'No dose adjustment is needed regardless of renal function, as digoxin is metabolised entirely by the liver', false, 'Ruled out because digoxin is predominantly renally, not hepatically, cleared, making renal function a key determinant of appropriate dosing, contrary to this statement.', 1),
('fa000000-0000-0000-0000-000000000025', 'B', 'The dose should be increased in renal impairment to overcome reduced absorption', false, 'Ruled out because renal impairment does not reduce digoxin absorption; it reduces renal clearance, meaning a dose reduction, not an increase, is required to avoid accumulation and toxicity.', 2),
('fa000000-0000-0000-0000-000000000025', 'C', 'Digoxin is predominantly renally cleared, so a lower dose is required in significant renal impairment, with therapeutic drug level monitoring to avoid toxicity', true, 'Correct. Digoxin is predominantly excreted unchanged by the kidneys, so significant renal impairment substantially reduces its clearance, risking accumulation and toxicity (nausea, visual disturbance, arrhythmias) at standard doses; a lower dose is required, with digoxin level monitoring (interpreted alongside clinical assessment and electrolytes, particularly potassium) used to guide safe, effective dosing.', 3),
('fa000000-0000-0000-0000-000000000025', 'D', 'Digoxin toxicity risk is unrelated to renal function', false, 'Ruled out because renal function is a specific, critical determinant of digoxin toxicity risk, given its predominantly renal route of elimination.', 4),
('fa000000-0000-0000-0000-000000000025', 'E', 'Digoxin levels should never be measured regardless of renal function or clinical concern', false, 'Ruled out because therapeutic drug level monitoring is a valuable and often necessary tool for guiding safe digoxin dosing, particularly relevant in renal impairment or when toxicity is clinically suspected.', 5),
('fa000000-0000-0000-0000-000000000026', 'A', 'First-order kinetics throughout the entire dose range', false, 'Ruled out because although phenytoin follows first-order kinetics at lower doses, it transitions to zero-order kinetics once metabolic enzymes become saturated at doses within the therapeutic range, which is the specific phenomenon described here.', 1),
('fa000000-0000-0000-0000-000000000026', 'B', 'Zero-order (saturation) kinetics', true, 'Correct. Phenytoin exhibits zero-order kinetics at doses within or above the therapeutic range, where the metabolic enzymes become saturated; beyond this saturation point, a constant amount (rather than a constant proportion) of drug is metabolised per unit time, meaning small dose increases can produce disproportionately large, unpredictable rises in plasma concentration, in contrast to the more predictable, proportional relationship seen with first-order kinetics.', 2),
('fa000000-0000-0000-0000-000000000026', 'C', 'Second-order kinetics', false, 'Ruled out because second-order kinetics is not a standard pharmacokinetic model applied to drug elimination in this context; the relevant distinction being described is between first-order and zero-order kinetics.', 3),
('fa000000-0000-0000-0000-000000000026', 'D', 'Non-linear kinetics unrelated to enzyme saturation', false, $x$Ruled out because the specific mechanism underlying phenytoin's non-linear pharmacokinetics is enzyme saturation (zero-order kinetics), not an unrelated non-linear process.$x$, 4),
('fa000000-0000-0000-0000-000000000026', 'E', 'This pattern only applies to renally cleared drugs, not hepatically metabolised drugs like phenytoin', false, 'Ruled out because zero-order kinetics from enzyme saturation is a hepatic metabolic phenomenon, directly relevant to phenytoin (a hepatically metabolised drug), not something limited to renally cleared drugs.', 5),
('fa000000-0000-0000-0000-000000000027', 'A', 'Such drugs are always very effectively removed by haemodialysis', false, 'Ruled out because this is the opposite of the typical relationship; drugs with a large volume of distribution are generally poorly, not effectively, removed by dialysis.', 1),
('fa000000-0000-0000-0000-000000000027', 'B', 'Volume of distribution has no relevance to dialysis clearance considerations', false, 'Ruled out because volume of distribution is a key pharmacokinetic parameter directly relevant to predicting whether dialysis will be an effective removal strategy in overdose.', 2),
('fa000000-0000-0000-0000-000000000027', 'C', 'Such drugs are typically poorly removed by haemodialysis, as most of the drug resides outside the plasma compartment that dialysis directly accesses', true, 'Correct. A large volume of distribution indicates that most of the drug is distributed into tissues rather than remaining in the plasma; since haemodialysis primarily removes drug from the blood/plasma compartment, drugs with a large volume of distribution (e.g. tricyclic antidepressants, digoxin) are typically poorly cleared by dialysis, as tissue-bound drug continues to redistribute back into plasma even as dialysis removes what little is present there.', 3),
('fa000000-0000-0000-0000-000000000027', 'D', 'A large volume of distribution means the drug is confined mostly to the plasma compartment', false, 'Ruled out because this is the opposite of what a large volume of distribution indicates; it reflects extensive tissue distribution, not plasma confinement.', 4),
('fa000000-0000-0000-0000-000000000027', 'E', 'Volume of distribution only matters for renally cleared drugs, not for drugs cleared by other routes', false, $x$Ruled out because volume of distribution is a relevant pharmacokinetic parameter regardless of the drug's specific clearance route, including its relevance to considering dialysis as a removal strategy.$x$, 5),
('fa000000-0000-0000-0000-000000000028', 'A', 'Steady state is reached after approximately four to five half-lives of regular dosing', true, $x$Correct. With regular dosing at fixed intervals, a drug's plasma concentration progressively rises and then plateaus once the amount eliminated per dosing interval equals the amount administered; this steady state is reached after approximately four to five half-lives, explaining why a drug with a 24-hour half-life takes around four to five days of daily dosing to reach a stable, predictable concentration.$x$, 1),
('fa000000-0000-0000-0000-000000000028', 'B', $x$Steady state has no relationship to a drug's half-life$x$, false, $x$Ruled out because the time to reach steady state is directly and predictably related to a drug's half-life (approximately four to five half-lives), making this statement incorrect.$x$, 2),
('fa000000-0000-0000-0000-000000000028', 'C', 'Steady state is reached immediately after the first dose of any medication', false, 'Ruled out because steady state is reached only after several half-lives of regular dosing, not immediately after a single dose, except in the specific case of a loading dose strategy designed to achieve a target concentration more rapidly.', 3),
('fa000000-0000-0000-0000-000000000028', 'D', 'Steady state can only be achieved with intravenous, not oral, dosing', false, $x$Ruled out because steady state can be achieved with regular dosing via any appropriate route, including oral dosing, provided dosing is continued at a consistent interval relative to the drug's half-life.$x$, 4),
('fa000000-0000-0000-0000-000000000028', 'E', 'The time to steady state is the same for all drugs regardless of their half-life', false, $x$Ruled out because the time to reach steady state varies directly with a drug's specific half-life; drugs with longer half-lives take correspondingly longer to reach steady state than those with shorter half-lives.$x$, 5),
('fa000000-0000-0000-0000-000000000029', 'A', 'A loading dose is given purely to test for allergic reactions before full treatment', false, 'Ruled out because this is not the pharmacokinetic rationale for a loading dose; its purpose is to achieve a therapeutic concentration rapidly, not to serve as an allergy test.', 1),
('fa000000-0000-0000-0000-000000000029', 'B', 'Loading doses are only relevant for drugs with a short half-life', false, 'Ruled out because loading doses are specifically most relevant and useful for drugs with a long half-life, where the time to reach steady state through regular dosing alone would otherwise be substantial; short half-life drugs reach steady state relatively quickly without needing this strategy.', 2),
('fa000000-0000-0000-0000-000000000029', 'C', $x$A loading dose permanently changes the drug's half-life for all subsequent doses$x$, false, $x$Ruled out because a loading dose does not alter the drug's inherent half-life; it simply achieves a target concentration more rapidly, after which regular maintenance dosing sustains that level based on the drug's normal pharmacokinetic properties.$x$, 3),
('fa000000-0000-0000-0000-000000000029', 'D', 'A loading dose allows a therapeutic plasma concentration to be achieved rapidly, rather than waiting the several half-lives otherwise required to reach steady state through regular dosing alone', true, $x$Correct. For drugs with a long half-life, waiting for steady state to be reached through regular maintenance dosing alone (requiring four to five half-lives) would delay achieving an effective therapeutic concentration; a loading dose, calculated based on the desired target concentration and the drug's volume of distribution, allows this therapeutic level to be reached rapidly, with maintenance dosing then continued to sustain it.$x$, 4),
('fa000000-0000-0000-0000-000000000029', 'E', 'Loading doses are given to reduce the total cumulative dose the patient will receive overall', false, 'Ruled out because this does not reflect the pharmacokinetic rationale for loading doses; their purpose is about the speed of reaching a therapeutic concentration, not reducing overall cumulative dosing.', 5),
('fa000000-0000-0000-0000-000000000030', 'A', 'Zero-order kinetics', false, 'Ruled out because zero-order kinetics describes saturation of elimination pathways at high drug concentrations, an unrelated concept to the pre-systemic hepatic metabolism being described here.', 1),
('fa000000-0000-0000-0000-000000000030', 'B', 'Volume of distribution', false, 'Ruled out because volume of distribution describes the extent of tissue distribution relative to plasma concentration, not the pre-systemic hepatic metabolism affecting oral bioavailability described here.', 2),
('fa000000-0000-0000-0000-000000000030', 'C', 'Steady state', false, 'Ruled out because steady state describes the plateau plasma concentration reached with regular dosing, an unrelated concept to the pre-systemic metabolism phenomenon being described.', 3),
('fa000000-0000-0000-0000-000000000030', 'D', 'Renal clearance', false, 'Ruled out because the phenomenon described specifically relates to hepatic (not renal) metabolism occurring before a drug reaches systemic circulation via the oral route.', 4),
('fa000000-0000-0000-0000-000000000030', 'E', 'First-pass metabolism', true, 'Correct. First-pass metabolism describes the extensive hepatic (and sometimes intestinal) metabolism that orally administered drugs undergo before reaching the systemic circulation via the portal venous system, substantially reducing the proportion of the administered dose (bioavailability) that reaches systemic circulation compared with intravenous administration, which bypasses this effect entirely.', 5),
('fa000000-0000-0000-0000-000000000031', 'A', 'Increased risk of bleeding due to excessive clopidogrel activity', false, 'Ruled out because poor metaboliser status results in reduced, not increased, active drug formation and antiplatelet effect, the opposite of an excessive-activity, increased-bleeding-risk scenario.', 1),
('fa000000-0000-0000-0000-000000000031', 'B', 'No clinical relevance, as clopidogrel does not require metabolic activation', false, 'Ruled out because clopidogrel specifically is a prodrug requiring hepatic CYP2C19-mediated activation to exert its antiplatelet effect, making this genetic variation directly clinically relevant.', 2),
('fa000000-0000-0000-0000-000000000031', 'C', 'Reduced conversion of clopidogrel to its active metabolite, potentially resulting in reduced antiplatelet effect and increased risk of stent thrombosis', true, 'Correct. Clopidogrel is a prodrug requiring hepatic activation via CYP2C19 to its active metabolite; patients who are CYP2C19 poor metabolisers generate less active drug, resulting in reduced antiplatelet effect and an increased risk of adverse cardiovascular events, including stent thrombosis, potentially warranting consideration of an alternative antiplatelet agent not dependent on this specific metabolic activation pathway (e.g. ticagrelor or prasugrel).', 3),
('fa000000-0000-0000-0000-000000000031', 'D', 'Enhanced clopidogrel effect due to increased CYP2C19 activity', false, 'Ruled out because a poor metaboliser genotype describes reduced, not increased or enhanced, CYP2C19 enzyme activity.', 4),
('fa000000-0000-0000-0000-000000000031', 'E', 'This finding is only relevant to drugs metabolised by CYP3A4, not CYP2C19', false, 'Ruled out because clopidogrel activation specifically depends on CYP2C19, making this genetic variant directly and specifically relevant to clopidogrel, not an unrelated CYP enzyme.', 5),
('fa000000-0000-0000-0000-000000000032', 'A', 'No change in free drug fraction occurs regardless of albumin level', false, 'Ruled out because albumin binding directly determines the free fraction of highly protein-bound drugs; hypoalbuminaemia meaningfully increases the free fraction for a given total concentration.', 1),
('fa000000-0000-0000-0000-000000000032', 'B', 'Hypoalbuminaemia reduces the free fraction of highly protein-bound drugs', false, 'Ruled out because this is the opposite of the correct relationship; reduced albumin means less binding capacity, increasing (not reducing) the free fraction of highly protein-bound drugs.', 2),
('fa000000-0000-0000-0000-000000000032', 'C', 'Standard total drug level measurements always accurately reflect toxicity risk regardless of albumin status', false, 'Ruled out because in significant hypoalbuminaemia, a standard total level can be misleading, as it does not distinguish the (increased) free, active fraction from the (reduced) bound fraction, potentially underestimating true toxicity risk.', 3),
('fa000000-0000-0000-0000-000000000032', 'D', 'This principle only applies to drugs that are renally, not hepatically, metabolised', false, 'Ruled out because protein binding and the effect of hypoalbuminaemia on free drug fraction is relevant to any highly protein-bound drug, regardless of its specific metabolic or clearance pathway.', 4),
('fa000000-0000-0000-0000-000000000032', 'E', 'A higher proportion of unbound (free, pharmacologically active) drug for a given total plasma concentration, meaning a standard total drug level may underestimate her true risk of toxicity', true, $x$Correct. Highly protein-bound drugs like phenytoin rely on albumin binding to limit the free, pharmacologically active fraction; in hypoalbuminaemia, a smaller proportion of the drug is bound, increasing the free fraction for a given total plasma concentration, meaning a standard total phenytoin level (which does not distinguish bound from free drug) may appear 'normal' while the patient is actually at increased risk of toxicity from the elevated free fraction, sometimes requiring correction formulas or measurement of free phenytoin levels.$x$, 5),
('fa000000-0000-0000-0000-000000000033', 'A', 'Standard adult doses should always be used regardless of age, as pharmacokinetics do not change with normal ageing', false, 'Ruled out because this directly contradicts the recognised physiological changes affecting drug pharmacokinetics with normal ageing, which generally necessitate more cautious dosing.', 1),
('fa000000-0000-0000-0000-000000000033', 'B', $x$Start at a lower dose and titrate cautiously ('start low, go slow'), reflecting generally reduced drug clearance and increased sensitivity in older adults$x$, true, $x$Correct. Age-related physiological changes -- reduced hepatic blood flow and enzyme activity, reduced renal function, altered body composition affecting volume of distribution, and often increased receptor sensitivity -- collectively mean older adults generally require lower starting doses with more cautious titration ('start low, go slow') to achieve therapeutic effect while minimising the increased risk of adverse drug effects seen in this population.$x$, 2),
('fa000000-0000-0000-0000-000000000033', 'C', 'Older patients should always receive higher doses to overcome age-related changes', false, 'Ruled out because this is the opposite of the appropriate general principle; reduced clearance and increased sensitivity generally necessitate lower, not higher, doses in older adults.', 3),
('fa000000-0000-0000-0000-000000000033', 'D', 'Age-related pharmacokinetic changes only affect renally cleared drugs, not hepatically metabolised drugs', false, 'Ruled out because both hepatic (reduced blood flow, reduced enzyme activity) and renal age-related changes are relevant, affecting drugs cleared by either route, not renally cleared drugs alone.', 4),
('fa000000-0000-0000-0000-000000000033', 'E', 'No dose adjustment is ever needed in older adults provided renal function is normal', false, 'Ruled out because pharmacokinetic changes in older adults extend beyond renal function alone (including hepatic changes and altered body composition/volume of distribution), meaning normal renal function alone does not exclude the need for cautious dosing consideration.', 5),
('fa000000-0000-0000-0000-000000000034', 'A', 'A classic IgE-mediated type I hypersensitivity reaction, identical in mechanism to a penicillin allergy', false, 'Ruled out because ACE inhibitor angioedema is a non-allergic, bradykinin-mediated reaction, distinct from IgE-mediated type I hypersensitivity reactions such as penicillin allergy, which is why it typically lacks urticaria and does not respond reliably to standard allergy treatments.', 1),
('fa000000-0000-0000-0000-000000000034', 'B', 'Direct mast cell degranulation from a toxic drug effect', false, 'Ruled out because the mechanism of ACE inhibitor-induced angioedema is bradykinin accumulation from reduced breakdown, not direct toxic mast cell degranulation.', 2),
('fa000000-0000-0000-0000-000000000034', 'C', 'A dose-independent genetic enzyme deficiency present from birth, unrelated to the ACE inhibitor', false, 'Ruled out because although some individuals may have genetic susceptibility factors, the reaction is specifically triggered by ACE inhibitor use through its known pharmacological mechanism (bradykinin accumulation), not an unrelated pre-existing condition.', 3),
('fa000000-0000-0000-0000-000000000034', 'D', 'Bradykinin accumulation due to reduced ACE-mediated breakdown, causing non-allergic angioedema', true, 'Correct. ACE inhibitors reduce the breakdown of bradykinin (normally degraded by ACE alongside its role in the renin-angiotensin system); accumulated bradykinin causes increased vascular permeability and angioedema, a non-allergic (non-IgE-mediated) reaction that classically lacks urticaria, can occur at any point during treatment (including after a long period of uneventful use), and does not respond reliably to antihistamines or adrenaline in the way allergic angioedema does, instead requiring drug withdrawal and airway monitoring/support.', 4),
('fa000000-0000-0000-0000-000000000034', 'E', 'Delayed type IV hypersensitivity mediated by T-cells', false, 'Ruled out because ACE inhibitor angioedema is a bradykinin-mediated, non-immunological reaction, not a T-cell-mediated delayed hypersensitivity reaction (which would present differently, e.g. as a delayed rash).', 5),
('fa000000-0000-0000-0000-000000000035', 'A', 'Methotrexate-induced bone marrow suppression causing severe neutropenia, requiring urgent assessment for neutropenic sepsis', true, 'Correct. Methotrexate can cause bone marrow suppression, including severe neutropenia, presenting with infective symptoms (sore throat, fever, mouth ulcers) due to impaired immune defence; this combination of symptoms and a very low neutrophil count in a patient on methotrexate requires urgent assessment for neutropenic sepsis, immediate methotrexate cessation, and prompt broad-spectrum antibiotics if sepsis criteria are met, given the life-threatening potential of untreated neutropenic sepsis.', 1),
('fa000000-0000-0000-0000-000000000035', 'B', 'A simple, self-limiting viral upper respiratory tract infection unrelated to his medication', false, 'Ruled out because the markedly low neutrophil count in a patient on methotrexate is a specific, serious adverse drug reaction requiring urgent action, not simply a self-limiting unrelated viral illness.', 2),
('fa000000-0000-0000-0000-000000000035', 'C', 'An expected, harmless finding requiring no specific action or medication review', false, 'Ruled out because a neutrophil count this low represents severe, dangerous neutropenia with significant infection risk, requiring urgent action (methotrexate cessation, sepsis assessment), not being dismissed as harmless.', 3),
('fa000000-0000-0000-0000-000000000035', 'D', 'Rheumatoid arthritis disease flare directly causing the abnormal blood count', false, $x$Ruled out because although rheumatoid arthritis itself can rarely cause cytopenias (e.g. Felty's syndrome), the clinical context of methotrexate therapy and this presentation should specifically prompt consideration of methotrexate-induced bone marrow suppression as the most likely and most urgent explanation to act on.$x$, 4),
('fa000000-0000-0000-0000-000000000035', 'E', 'Iron deficiency anaemia unrelated to his methotrexate therapy', false, 'Ruled out because the presentation (severe neutropenia, infective symptoms) is not consistent with iron deficiency anaemia, and methotrexate-induced bone marrow suppression is the key, most urgent diagnosis to consider and act upon here.', 5),
('fa000000-0000-0000-0000-000000000036', 'A', 'Serotonin syndrome from an unrelated serotonergic medication', false, 'Ruled out because although serotonin syndrome shares some overlapping features (hyperthermia, autonomic instability), the specific clinical context (recent antipsychotic initiation, prominent rigidity) and absence of a described serotonergic drug trigger points to neuroleptic malignant syndrome specifically.', 1),
('fa000000-0000-0000-0000-000000000036', 'B', 'A simple viral illness causing incidental fever, unrelated to his new medication', false, 'Ruled out because this specific combination of severe rigidity, autonomic instability, confusion and markedly raised creatine kinase, occurring in the context of new antipsychotic use, is not consistent with a simple, unrelated viral illness and represents a specific, dangerous drug reaction requiring urgent recognition.', 2),
('fa000000-0000-0000-0000-000000000036', 'C', 'Acute dystonia, a mild and self-limiting antipsychotic side effect', false, 'Ruled out because acute dystonia (sustained muscle spasm, often affecting the neck or eyes) is a distinct, generally less severe extrapyramidal reaction; it does not typically cause the systemic features (hyperthermia, autonomic instability, markedly elevated CK) seen in this life-threatening presentation.', 3),
('fa000000-0000-0000-0000-000000000036', 'D', 'Neuroleptic malignant syndrome', true, 'Correct. The combination of hyperthermia, severe muscle rigidity, altered mental state, autonomic instability and markedly elevated creatine kinase in a patient recently started on (or having had a dose increase of) an antipsychotic is characteristic of neuroleptic malignant syndrome, a rare but life-threatening reaction thought to relate to central dopamine receptor blockade, requiring immediate antipsychotic cessation, supportive care (cooling, hydration, monitoring for rhabdomyolysis-related renal injury), and specialist input, with specific treatments such as dantrolene or bromocriptine considered in severe cases.', 4),
('fa000000-0000-0000-0000-000000000036', 'E', 'Malignant hyperthermia, specifically triggered by volatile anaesthetic exposure', false, 'Ruled out because malignant hyperthermia is specifically triggered by volatile anaesthetic agents or suxamethonium, not antipsychotic medication; the clinical context here (recent antipsychotic initiation) points to neuroleptic malignant syndrome instead, though the two conditions share some overlapping features.', 5),
('fa000000-0000-0000-0000-000000000037', 'A', 'Hydroxychloroquine-induced retinopathy', true, 'Correct. Long-term hydroxychloroquine use carries a risk of retinopathy, related to cumulative dose and duration of treatment, which can progress to irreversible visual loss if unrecognised; regular ophthalmic screening (typically including visual assessment and specific retinal imaging/electrophysiological testing) is recommended to detect early, often initially asymptomatic changes before significant, irreversible visual impairment develops.', 1),
('fa000000-0000-0000-0000-000000000037', 'B', 'Peripheral neuropathy from cumulative nerve toxicity', false, 'Ruled out because the specific, well-recognised cumulative toxicity requiring regular screening with hydroxychloroquine is retinopathy, not peripheral neuropathy.', 2),
('fa000000-0000-0000-0000-000000000037', 'C', 'Cumulative nephrotoxicity requiring regular renal function monitoring', false, $x$Ruled out because hydroxychloroquine's specific recognised cumulative toxicity requiring dedicated regular screening is retinal, not renal, in nature.$x$, 3),
('fa000000-0000-0000-0000-000000000037', 'D', 'Progressive, irreversible hepatotoxicity requiring regular liver function tests as the primary monitoring focus', false, 'Ruled out because although liver function may be checked as part of general monitoring, the specific, well-recognised cumulative toxicity of hydroxychloroquine requiring dedicated regular screening is retinopathy, not hepatotoxicity.', 4),
('fa000000-0000-0000-0000-000000000037', 'E', 'Cumulative bone marrow suppression requiring regular full blood count as the primary screening focus', false, 'Ruled out because the specific, well-recognised cumulative toxicity requiring dedicated regular monitoring with hydroxychloroquine is retinopathy, not bone marrow suppression.', 5),
('fa000000-0000-0000-0000-000000000038', 'A', 'Hepatotoxicity, the primary serious adverse effect requiring liver function monitoring', false, 'Ruled out because although hepatotoxicity is a significant and separately monitored risk of isoniazid (via regular liver function tests), pyridoxine supplementation specifically addresses the separate risk of peripheral neuropathy, not hepatotoxicity.', 1),
('fa000000-0000-0000-0000-000000000038', 'B', 'Ototoxicity, a recognised adverse effect of aminoglycoside antibiotics', false, 'Ruled out because ototoxicity is not a recognised isoniazid adverse effect requiring this specific prophylactic co-prescription; it is more relevant to aminoglycoside antibiotics.', 2),
('fa000000-0000-0000-0000-000000000038', 'C', 'Nephrotoxicity requiring pyridoxine as a renal-protective agent', false, 'Ruled out because pyridoxine co-prescription with isoniazid is specifically to reduce peripheral neuropathy risk via its role in vitamin B6-dependent metabolic pathways, not as a renal-protective strategy.', 3),
('fa000000-0000-0000-0000-000000000038', 'D', $x$Bone marrow suppression, prevented by pyridoxine's haematological protective effect$x$, false, $x$Ruled out because pyridoxine's protective role with isoniazid relates specifically to reducing peripheral neuropathy risk, not to any haematological/bone marrow protective mechanism.$x$, 4),
('fa000000-0000-0000-0000-000000000038', 'E', 'Peripheral neuropathy, caused by isoniazid-induced pyridoxine (vitamin B6) depletion', true, 'Correct. Isoniazid can cause peripheral neuropathy through interference with pyridoxine (vitamin B6) metabolism, and co-prescribing pyridoxine supplementation is a recognised prophylactic strategy to reduce this risk, particularly relevant in patients with other risk factors for neuropathy (such as diabetes, alcohol excess, or malnutrition), though isoniazid also carries other important recognised risks (notably hepatotoxicity) that pyridoxine does not address.', 5),
('fa000000-0000-0000-0000-000000000039', 'A', 'Amiodarone only affects cardiac rhythm and monitoring is purely to confirm ongoing arrhythmia control', false, 'Ruled out because amiodarone has well-recognised, clinically significant extra-cardiac (thyroid, hepatic, pulmonary and other) toxicity risks, which is precisely why this broader, multi-system monitoring is undertaken, not simply monitoring for rhythm control.', 1),
('fa000000-0000-0000-0000-000000000039', 'B', 'Amiodarone has recognised potential for multi-organ toxicity (thyroid, hepatic and pulmonary, among others), requiring this comprehensive, structured monitoring approach', true, 'Correct. Amiodarone, structurally related to thyroxine and highly lipophilic with a very long half-life, has recognised potential for a wide range of adverse effects including thyroid dysfunction (both hypo- and hyperthyroidism), hepatotoxicity, and pulmonary toxicity (including potentially serious pulmonary fibrosis), among others (e.g. corneal deposits, photosensitivity, peripheral neuropathy), necessitating this structured, multi-system regular monitoring approach for early detection.', 2),
('fa000000-0000-0000-0000-000000000039', 'C', 'This monitoring is only relevant during the first month of treatment, after which it can be safely stopped', false, 'Ruled out because amiodarone toxicity risks (particularly given its very long half-life and tissue accumulation) persist throughout treatment, meaning structured monitoring should continue for the duration of therapy, not just an initial period.', 3),
('fa000000-0000-0000-0000-000000000039', 'D', 'Thyroid dysfunction is the only recognised adverse effect requiring monitoring with amiodarone', false, 'Ruled out because although thyroid dysfunction is an important and well-recognised risk, amiodarone also carries significant hepatic, pulmonary and other toxicity risks, justifying the broader, multi-system monitoring approach described, not thyroid monitoring alone.', 4),
('fa000000-0000-0000-0000-000000000039', 'E', 'This monitoring has no evidence base and is performed purely for medicolegal reasons', false, $x$Ruled out because this monitoring reflects genuine, well-established evidence regarding amiodarone's recognised multi-organ toxicity profile, not being without clinical basis.$x$, 5),
('fa000000-0000-0000-0000-000000000040', 'A', 'Anaphylaxis requiring immediate intramuscular adrenaline and permanent avoidance of vancomycin', false, 'Ruled out because this presentation (flushing/rash without hypotension or respiratory compromise, related to infusion rate) is more consistent with red man syndrome than anaphylaxis, and does not require immediate adrenaline; slowing the infusion is the appropriate initial approach, distinguishing it from a true anaphylactic emergency.', 1),
('fa000000-0000-0000-0000-000000000040', 'B', 'A simple coincidental viral exanthem unrelated to the vancomycin infusion', false, 'Ruled out because the temporal relationship to the vancomycin infusion and the classic pattern described (flushing/rash without other systemic compromise) point specifically to a recognised vancomycin-related reaction (red man syndrome), not an unrelated coincidental viral illness.', 2),
('fa000000-0000-0000-0000-000000000040', 'C', 'Vancomycin (red man syndrome), a non-allergic, infusion-rate-related histamine release reaction, managed by slowing or temporarily pausing the infusion rather than necessarily stopping vancomycin altogether', true, $x$Correct. 'Red man syndrome' is a non-IgE-mediated reaction related to direct mast cell histamine release, typically associated with rapid vancomycin infusion rates; it is managed by slowing the infusion rate (and pausing temporarily if needed until symptoms resolve), with antihistamines sometimes used, rather than necessarily discontinuing vancomycin entirely, as this differs mechanistically from a true IgE-mediated vancomycin allergy.$x$, 3),
('fa000000-0000-0000-0000-000000000040', 'D', 'Vancomycin-induced neutropenia, requiring an urgent full blood count as the priority action', false, 'Ruled out because this acute, infusion-related flushing/rash presentation is not consistent with neutropenia (which would present differently and is not an acute infusion-reaction phenomenon); it is characteristic of red man syndrome.', 4),
('fa000000-0000-0000-0000-000000000040', 'E', 'Serotonin syndrome from a drug interaction with vancomycin', false, 'Ruled out because vancomycin is not typically implicated in serotonin syndrome, and this presentation (isolated flushing/rash related to infusion) is specifically characteristic of red man syndrome, not serotonin syndrome.', 5),
('fa000000-0000-0000-0000-000000000041', 'A', 'Simple, mild maculopapular drug rash unrelated to any specific genetic marker', false, 'Ruled out because HLA-B*1502 screening is specifically designed to identify risk of severe, life-threatening Stevens-Johnson syndrome/toxic epidermal necrolysis, not to predict or prevent a mild, non-specific maculopapular rash.', 1),
('fa000000-0000-0000-0000-000000000041', 'B', 'Stevens-Johnson syndrome/toxic epidermal necrolysis, associated with the HLA-B*1502 allele in carbamazepine-treated patients of certain ancestries', true, 'Correct. Carbamazepine carries a well-recognised risk of severe cutaneous adverse reactions (Stevens-Johnson syndrome and toxic epidermal necrolysis), strongly associated with the HLA-B*1502 allele, which is more prevalent in individuals of Southeast Asian (including Han Chinese, Thai and related) ancestry; pre-treatment genetic screening for this allele in at-risk populations allows avoidance of carbamazepine (in favour of an alternative anti-epileptic) in those found to carry it, substantially reducing this severe reaction risk.', 2),
('fa000000-0000-0000-0000-000000000041', 'C', 'Hepatotoxicity, prevented by avoiding carbamazepine in HLA-B*1502-positive patients', false, 'Ruled out because HLA-B*1502 is specifically associated with severe cutaneous reactions (Stevens-Johnson syndrome/toxic epidermal necrolysis), not hepatotoxicity, which is monitored separately.', 3),
('fa000000-0000-0000-0000-000000000041', 'D', 'Bone marrow suppression, the specific adverse effect this genetic screening addresses', false, 'Ruled out because although carbamazepine can rarely cause bone marrow suppression (monitored through other means), the HLA-B*1502 screening specifically relates to severe cutaneous reaction risk, not bone marrow toxicity.', 4),
('fa000000-0000-0000-0000-000000000041', 'E', 'Hyponatraemia, the adverse effect this pre-treatment screening is designed to predict', false, 'Ruled out because although carbamazepine can cause hyponatraemia (via SIADH-like effect, monitored through electrolyte checks), this is not what HLA-B*1502 screening is designed to predict; it specifically relates to severe cutaneous reaction risk.', 5),
('fa000000-0000-0000-0000-000000000042', 'A', $x$Erythromycin induces cytochrome P450 enzymes, reducing warfarin's anticoagulant effect$x$, false, 'Ruled out because this describes enzyme induction (which would reduce, not increase, warfarin effect and INR); erythromycin is an enzyme inhibitor, consistent with the observed increased INR.', 1),
('fa000000-0000-0000-0000-000000000042', 'B', 'Erythromycin displaces warfarin from plasma protein binding sites, with no relevant metabolic interaction', false, 'Ruled out because although protein-binding displacement interactions exist for some drug combinations, the clinically dominant and relevant mechanism for this specific interaction is cytochrome P450 enzyme inhibition by erythromycin.', 2),
('fa000000-0000-0000-0000-000000000042', 'C', 'Erythromycin has no recognised interaction with warfarin, and this INR rise is coincidental', false, 'Ruled out because erythromycin has a well-recognised, clinically significant interaction with warfarin via CYP450 inhibition, making this temporal association with his markedly elevated INR unlikely to be coincidental.', 3),
('fa000000-0000-0000-0000-000000000042', 'D', $x$Erythromycin inhibits cytochrome P450 enzymes responsible for warfarin metabolism, increasing warfarin's anticoagulant effect$x$, true, 'Correct. Erythromycin (and other macrolides) inhibit hepatic cytochrome P450 enzymes (including those involved in warfarin metabolism), reducing warfarin clearance and increasing its plasma concentration and anticoagulant effect, raising bleeding risk; this interaction highlights the importance of medication reconciliation and INR monitoring whenever a new interacting drug is started in a patient on warfarin.', 4),
('fa000000-0000-0000-0000-000000000042', 'E', 'Erythromycin directly damages hepatic synthetic function, reducing clotting factor production', false, 'Ruled out because the mechanism of this interaction is pharmacokinetic (CYP450 enzyme inhibition affecting warfarin metabolism), not direct hepatotoxic impairment of clotting factor synthesis.', 5),
('fa000000-0000-0000-0000-000000000043', 'A', $x$Carbamazepine, a potent hepatic enzyme inducer, increased the metabolism of the oral contraceptive's hormonal components, reducing its efficacy$x$, true, $x$Correct. Carbamazepine is a potent inducer of hepatic cytochrome P450 enzymes, increasing the metabolism (and thus reducing plasma levels and efficacy) of the combined oral contraceptive pill's hormonal components, significantly increasing the risk of contraceptive failure; enzyme-inducing anti-epileptic drugs require specific contraceptive counselling regarding this interaction and consideration of alternative, non-hormonally-interacting contraceptive methods or dose adjustments.$x$, 1),
('fa000000-0000-0000-0000-000000000043', 'B', 'Carbamazepine inhibits hepatic enzyme metabolism of the contraceptive pill, which should have increased, not decreased, its effectiveness', false, 'Ruled out because carbamazepine is an enzyme inducer, not inhibitor; enzyme induction increases hormone metabolism and clearance, reducing (not increasing) contraceptive efficacy, consistent with this contraceptive failure.', 2),
('fa000000-0000-0000-0000-000000000043', 'C', 'Oral contraceptive failure of this type is never related to concurrent anti-epileptic medication', false, 'Ruled out because this is a well-recognised, clinically important interaction between certain enzyme-inducing anti-epileptic drugs (including carbamazepine) and hormonal contraceptives, directly relevant to this scenario.', 3),
('fa000000-0000-0000-0000-000000000043', 'D', 'The contraceptive pill directly reduced carbamazepine levels, triggering a breakthrough seizure that caused the pregnancy', false, $x$Ruled out because this describes an unrelated, implausible causal chain; the relevant, well-recognised interaction is carbamazepine's enzyme-inducing effect reducing contraceptive efficacy, not the reverse.$x$, 4),
('fa000000-0000-0000-0000-000000000043', 'E', 'This outcome is simply due to standard, expected contraceptive pill failure rates unrelated to any drug interaction', false, 'Ruled out because the specific pharmacological interaction between carbamazepine (enzyme induction) and the hormonal contraceptive is a recognised, clinically significant cause of increased failure risk beyond baseline failure rates, and should be specifically considered and counselled for in this context.', 5),
('fa000000-0000-0000-0000-000000000044', 'A', 'Amiodarone has no recognised pharmacokinetic interaction with digoxin, and this dose reduction is unnecessary', false, 'Ruled out because amiodarone and digoxin have a well-recognised, clinically significant interaction (via P-glycoprotein inhibition) requiring proactive dose adjustment, not an interaction-free combination.', 1),
('fa000000-0000-0000-0000-000000000044', 'B', 'Amiodarone increases digoxin clearance, meaning the digoxin dose should be increased, not reduced, when co-prescribed', false, 'Ruled out because this is the opposite of the correct interaction; amiodarone reduces (via P-glycoprotein inhibition), not increases, digoxin clearance, meaning a dose reduction, not increase, is appropriate.', 2),
('fa000000-0000-0000-0000-000000000044', 'C', 'Amiodarone inhibits P-glycoprotein-mediated digoxin clearance, increasing digoxin levels and toxicity risk if the dose is not proactively reduced', true, $x$Correct. Amiodarone inhibits P-glycoprotein, a transporter involved in digoxin's renal and biliary clearance, and this interaction can significantly increase digoxin plasma levels; to avoid digoxin toxicity, a proactive dose reduction (commonly around 50%) is standard practice when amiodarone is co-prescribed, alongside digoxin level monitoring.$x$, 3),
('fa000000-0000-0000-0000-000000000044', 'D', 'The dose reduction is solely to manage a pharmacodynamic, not pharmacokinetic, interaction between the two drugs', false, 'Ruled out because the dominant, clinically significant mechanism here is a pharmacokinetic interaction (P-glycoprotein-mediated reduced digoxin clearance), not a pharmacodynamic interaction.', 4),
('fa000000-0000-0000-0000-000000000044', 'E', 'This dose reduction is a routine precaution unrelated to any specific interaction, applied to all new heart failure medications', false, 'Ruled out because this is a specific, well-recognised pharmacokinetic interaction between amiodarone and digoxin requiring deliberate dose adjustment, not a generic precaution applied indiscriminately to unrelated medications.', 5),
('fa000000-0000-0000-0000-000000000045', 'A', 'Simple opioid-induced sedation and constipation, unrelated to her antidepressant', false, 'Ruled out because this presentation (agitation, hyperreflexia, tremor, diarrhoea) is inconsistent with simple opioid sedation/constipation and is instead characteristic of serotonin syndrome from the SSRI-tramadol interaction.', 1),
('fa000000-0000-0000-0000-000000000045', 'B', 'Opioid withdrawal syndrome from insufficient tramadol dosing', false, 'Ruled out because this presentation occurred after starting, not withdrawing from, an opioid, and the specific symptom combination (with hyperreflexia particularly) points to serotonin syndrome from the drug interaction rather than opioid withdrawal.', 2),
('fa000000-0000-0000-0000-000000000045', 'C', 'Anticholinergic toxicity from a combined effect of her medications', false, 'Ruled out because the described features (hyperreflexia, diarrhoea, sweating) are not consistent with anticholinergic toxicity (which would more typically cause dry skin, urinary retention and reduced bowel sounds); this presentation is characteristic of serotonin syndrome instead.', 3),
('fa000000-0000-0000-0000-000000000045', 'D', 'A simple postoperative anxiety reaction unrelated to any drug interaction', false, 'Ruled out because the specific combination of features described (agitation, sweating, tremor, hyperreflexia, diarrhoea), occurring shortly after starting a serotonergic opioid in a patient on an SSRI, is characteristic of serotonin syndrome, not a non-specific anxiety reaction.', 4),
('fa000000-0000-0000-0000-000000000045', 'E', 'Serotonin syndrome, resulting from the additive serotonergic effects of combining an SSRI with tramadol (which also has serotonergic activity)', true, 'Correct. Tramadol has serotonergic activity (in addition to its opioid effects) and can precipitate serotonin syndrome when combined with other serotonergic drugs such as SSRIs; the combination of agitation, sweating, tremor, hyperreflexia and diarrhoea shortly after starting tramadol in a patient on citalopram is characteristic of this interaction, requiring both drugs to be stopped and supportive management, with severe cases requiring specific treatment (e.g. cyproheptadine) and intensive monitoring.', 5),
('fa000000-0000-0000-0000-000000000046', 'A', $x$This hyperkalaemia is unrelated to his medications and reflects primary Addison's disease$x$, false, 'Ruled out because this presentation is well explained by the recognised, additive hyperkalaemia risk of his specific medication combination, making a new unrelated primary adrenal insufficiency diagnosis a much less likely explanation to prioritise here.', 1),
('fa000000-0000-0000-0000-000000000046', 'B', 'Only the spironolactone is relevant to this hyperkalaemia, with the ACE inhibitor and NSAID being irrelevant bystanders', false, $x$Ruled out because although spironolactone contributes directly, the ACE inhibitor and NSAID also meaningfully contribute to this hyperkalaemia risk through their own additive mechanisms, together constituting the recognised 'triple whammy' interaction, not spironolactone acting in isolation.$x$, 2),
('fa000000-0000-0000-0000-000000000046', 'C', 'Ibuprofen has no relevant effect on renal function or potassium handling', false, 'Ruled out because NSAIDs, including ibuprofen, do have a relevant effect on renal perfusion/function and potassium handling through prostaglandin inhibition, contributing meaningfully to this combined hyperkalaemia and acute kidney injury risk.', 3),
('fa000000-0000-0000-0000-000000000046', 'D', 'This combination of medications is safe and requires no specific monitoring or action', false, 'Ruled out because this specific combination carries a well-recognised, clinically significant risk requiring proactive monitoring and, where hyperkalaemia or renal impairment occurs (as here), urgent action, not being considered a safe, no-monitoring-needed combination.', 4),
('fa000000-0000-0000-0000-000000000046', 'E', $x$The combination of an ACE inhibitor, NSAID and potassium-sparing diuretic ('triple whammy') has an additive effect on renal potassium handling and function, significantly increasing hyperkalaemia (and acute kidney injury) risk$x$, true, $x$Correct. This combination is a well-recognised 'triple whammy' interaction: ACE inhibitors reduce aldosterone-driven potassium excretion, NSAIDs reduce renal perfusion and glomerular filtration (via prostaglandin inhibition) and can independently impair potassium excretion, and spironolactone (a potassium-sparing, aldosterone-antagonist diuretic) directly promotes potassium retention; together, these combine to significantly increase the risk of both acute kidney injury and dangerous hyperkalaemia, requiring urgent review, likely stopping the NSAID (and reviewing the ACE inhibitor/spironolactone combination), and close monitoring.$x$, 5),
('fa000000-0000-0000-0000-000000000047', 'A', 'Clarithromycin inhibits CYP3A4-mediated simvastatin metabolism, increasing simvastatin levels and precipitating myopathy/rhabdomyolysis', true, 'Correct. Simvastatin is metabolised via CYP3A4, and clarithromycin (a potent CYP3A4 inhibitor) significantly reduces simvastatin clearance, increasing plasma levels and substantially raising the risk of statin-related myopathy and, in severe cases, rhabdomyolysis; this well-recognised interaction generally requires simvastatin to be withheld during clarithromycin treatment, or an alternative antibiotic or statin with less CYP3A4 dependence to be considered.', 1),
('fa000000-0000-0000-0000-000000000047', 'B', 'Clarithromycin induces CYP3A4 metabolism of simvastatin, which should have reduced, not increased, simvastatin-related toxicity risk', false, 'Ruled out because clarithromycin is a CYP3A4 inhibitor, not inducer; inhibition increases (not decreases) simvastatin levels and toxicity risk, consistent with this presentation.', 2),
('fa000000-0000-0000-0000-000000000047', 'C', 'This presentation is an unrelated, coincidental idiopathic myopathy with no connection to her new antibiotic', false, 'Ruled out because the clear temporal relationship and well-recognised pharmacological interaction between clarithromycin and simvastatin make this a much more likely, specific explanation than an unrelated coincidental idiopathic myopathy.', 3),
('fa000000-0000-0000-0000-000000000047', 'D', 'Simvastatin and clarithromycin have no relevant shared metabolic pathway or interaction', false, 'Ruled out because simvastatin and clarithromycin do share a clinically significant metabolic interaction via CYP3A4, directly relevant to this presentation of myopathy/rhabdomyolysis risk.', 4),
('fa000000-0000-0000-0000-000000000047', 'E', 'Clarithromycin directly damages skeletal muscle through a toxic effect unrelated to simvastatin metabolism', false, 'Ruled out because the mechanism of this interaction is pharmacokinetic (CYP3A4 inhibition raising simvastatin levels), not direct, simvastatin-independent muscle toxicity from clarithromycin itself.', 5),
('fa000000-0000-0000-0000-000000000048', 'A', 'Protease inhibitors have minimal interaction potential and require no specific medication review', false, 'Ruled out because protease inhibitors have among the highest interaction potential of any commonly used drug class, making careful, systematic medication review essential, not unnecessary.', 1),
('fa000000-0000-0000-0000-000000000048', 'B', 'Protease inhibitors only interact with other antiretroviral medications and no other drug classes', false, 'Ruled out because protease inhibitors have well-recognised, clinically significant interactions with a very wide range of non-antiretroviral drug classes, not being limited to interactions within antiretroviral therapy alone.', 2),
('fa000000-0000-0000-0000-000000000048', 'C', 'Protease inhibitors are potent enzyme inducers, reducing the levels of co-administered drugs', false, 'Ruled out because protease inhibitors are predominantly potent enzyme inhibitors (increasing, not reducing, co-administered drug levels for many affected drugs), not primarily enzyme inducers.', 3),
('fa000000-0000-0000-0000-000000000048', 'D', 'Protease inhibitors are potent inhibitors of CYP3A4 (and other enzymes/transporters), giving them a very broad potential for clinically significant interactions with many other commonly prescribed drugs', true, 'Correct. HIV protease inhibitors are among the most potent CYP3A4 inhibitors used clinically, and also affect other metabolic and transport pathways, giving them an unusually broad potential for significant drug interactions across many drug classes (including statins, some anticoagulants, certain antiarrhythmics, and many others); careful, systematic medication review is essential whenever starting or adjusting a protease inhibitor-based regimen to identify and manage these interactions.', 4),
('fa000000-0000-0000-0000-000000000048', 'E', 'Interaction risk with protease inhibitors is limited to drugs administered intravenously, not oral medications', false, 'Ruled out because protease inhibitor interactions are highly relevant to oral medications (through effects on hepatic and intestinal metabolism, as well as some transporters), not limited to intravenous drug administration.', 5),
('fa000000-0000-0000-0000-000000000049', 'A', 'Thiazide diuretics increase renal lithium clearance, which should have reduced, not increased, his lithium level', false, 'Ruled out because this is the opposite of the correct mechanism; thiazides reduce (not increase) renal lithium clearance through their effect on proximal tubular reabsorption, consistent with his elevated lithium level.', 1),
('fa000000-0000-0000-0000-000000000049', 'B', 'Thiazide diuretics reduce renal lithium clearance (via increased proximal tubular sodium and lithium reabsorption in response to diuretic-induced volume depletion), increasing lithium levels and precipitating toxicity', true, 'Correct. Thiazide diuretics cause mild volume depletion, triggering compensatory increased proximal tubular sodium (and, because lithium is handled similarly to sodium at this site, lithium) reabsorption, which reduces renal lithium clearance and can significantly raise lithium levels, precipitating toxicity; this is a well-recognised, clinically important interaction requiring caution, closer lithium level monitoring, or an alternative antihypertensive choice where possible.', 2),
('fa000000-0000-0000-0000-000000000049', 'C', 'This presentation is unrelated to the new diuretic and reflects a spontaneous relapse of his bipolar disorder', false, 'Ruled out because the clear temporal relationship with starting a thiazide diuretic and the classic biochemical/clinical picture (confusion, tremor, elevated lithium level) point specifically to a drug interaction precipitating lithium toxicity, not an unrelated psychiatric relapse.', 3),
('fa000000-0000-0000-0000-000000000049', 'D', 'Thiazide diuretics have no recognised interaction with lithium, and this is a coincidental finding', false, 'Ruled out because thiazide diuretics have a well-established, clinically significant interaction with lithium via reduced renal clearance, making this a recognised, not coincidental, interaction.', 4),
('fa000000-0000-0000-0000-000000000049', 'E', 'Loop diuretics and thiazide diuretics carry an identical, interchangeable lithium interaction risk profile', false, 'Ruled out because although loop diuretics can also affect lithium levels, thiazide diuretics are particularly strongly associated with this specific interaction mechanism, and the two diuretic classes are not simply interchangeable in this context without consideration of their differing effects and relative risk.', 5),
('fa000000-0000-0000-0000-000000000050', 'A', 'Trimethoprim has no relevant shared mechanism with methotrexate, and this presentation is coincidental', false, 'Ruled out because trimethoprim and methotrexate share a specific, clinically significant mechanistic overlap (both being antifolate agents via dihydrofolate reductase inhibition), making this a recognised, dangerous interaction rather than a coincidental presentation.', 1),
('fa000000-0000-0000-0000-000000000050', 'B', 'Trimethoprim induces hepatic enzymes that increase methotrexate clearance, which should have reduced, not increased, toxicity risk', false, 'Ruled out because the relevant mechanism is a pharmacodynamic additive antifolate effect (not altered hepatic clearance via enzyme induction), explaining the increased, not decreased, toxicity seen here.', 2),
('fa000000-0000-0000-0000-000000000050', 'C', 'Trimethoprim and methotrexate both inhibit dihydrofolate reductase, and their additive antifolate effect significantly increases the risk of severe bone marrow suppression', true, 'Correct. Both trimethoprim and methotrexate inhibit dihydrofolate reductase (an enzyme essential for folate metabolism and, in turn, DNA synthesis); combining them produces an additive antifolate effect, significantly increasing the risk of severe bone marrow suppression (pancytopenia) and mucosal toxicity, making this a well-recognised, dangerous combination that should generally be avoided, with an alternative antibiotic chosen for patients on methotrexate wherever possible.', 3),
('fa000000-0000-0000-0000-000000000050', 'D', 'This pancytopenia reflects an unrelated primary haematological malignancy requiring urgent unrelated investigation, with no connection to his medications', false, 'Ruled out because the clear temporal relationship with starting trimethoprim and the well-recognised, specific interaction mechanism with methotrexate make a drug-interaction-related cause far more likely to prioritise than an unrelated new primary haematological malignancy.', 4),
('fa000000-0000-0000-0000-000000000050', 'E', 'Trimethoprim only interacts with methotrexate when given intravenously, not via the oral route used for a urinary tract infection', false, 'Ruled out because this interaction is clinically significant with standard oral trimethoprim dosing (as commonly used for urinary tract infections), not limited to intravenous administration.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('fa000000-0000-0000-0000-000000000001', 'The paracetamol treatment nomogram plots plasma paracetamol concentration against time since ingestion to determine whether N-acetylcysteine is indicated, valid for single acute ingestions presenting within the appropriate time window.', 1),
('fa000000-0000-0000-0000-000000000001', 'N-acetylcysteine works by replenishing hepatic glutathione, which detoxifies NAPQI, the toxic metabolite responsible for paracetamol-induced hepatocellular necrosis when glutathione stores are overwhelmed.', 2),
('fa000000-0000-0000-0000-000000000001', 'Absence of symptoms at presentation does not exclude significant overdose risk, as paracetamol-induced hepatotoxicity classically develops with a delay, often becoming apparent from around 24-72 hours post-ingestion.', 3),
('fa000000-0000-0000-0000-000000000002', 'Late-presenting patients with evidence of hepatotoxicity should receive N-acetylcysteine immediately, regardless of paracetamol level or nomogram applicability, given its ongoing benefit even after significant liver injury has begun.', 1),
('fa000000-0000-0000-0000-000000000002', $x$King's College Hospital criteria (incorporating arterial pH, INR, creatinine, and hepatic encephalopathy grade) are used to identify patients with paracetamol-induced acute liver failure who may benefit from urgent liver transplantation.$x$, 2),
('fa000000-0000-0000-0000-000000000002', 'Coagulopathy (raised INR), renal impairment and acidosis together indicate severe hepatotoxicity with systemic complications, reflecting a high-risk presentation requiring urgent specialist (hepatology/liver transplant unit) involvement.', 3),
('fa000000-0000-0000-0000-000000000003', 'The triad of pinpoint pupils, respiratory depression and reduced consciousness is classic for opioid toxicity/overdose.', 1),
('fa000000-0000-0000-0000-000000000003', 'Naloxone acts as a competitive opioid receptor antagonist, rapidly reversing respiratory depression, though its shorter half-life compared with many opioids (particularly long-acting/modified-release formulations) means repeated dosing or an infusion may be required.', 2),
('fa000000-0000-0000-0000-000000000003', 'Close monitoring after naloxone administration is essential given the risk of recurrent respiratory depression as the naloxone effect wanes before the causative opioid has been fully cleared.', 3),
('fa000000-0000-0000-0000-000000000004', 'QRS widening on ECG is the key marker of sodium channel blockade-related cardiotoxicity in TCA overdose, guiding the specific need for sodium bicarbonate treatment.', 1),
('fa000000-0000-0000-0000-000000000004', 'Sodium bicarbonate works through two complementary mechanisms: increasing extracellular sodium (overcoming competitive channel blockade) and alkalinisation (reducing TCA binding affinity to cardiac sodium channels).', 2),
('fa000000-0000-0000-0000-000000000004', 'Standard class Ia/Ic anti-arrhythmics are specifically avoided in TCA overdose, as their similar sodium-channel blocking mechanism can exacerbate the cardiotoxicity rather than treat it.', 3),
('fa000000-0000-0000-0000-000000000005', 'ACE inhibitors and other drugs affecting renal sodium/water handling, alongside states of dehydration (e.g. from diarrhoeal illness), are well-recognised precipitants of lithium toxicity by reducing renal lithium clearance.', 1),
('fa000000-0000-0000-0000-000000000005', 'Classic features of lithium toxicity include coarse tremor, ataxia, confusion, vomiting and, in severe cases, seizures and arrhythmias, reflecting its narrow therapeutic index.', 2),
('fa000000-0000-0000-0000-000000000005', 'A confirmed serum lithium level guides management intensity, including the threshold for considering haemodialysis in severe or refractory toxicity, alongside general supportive care and fluid resuscitation.', 3),
('fa000000-0000-0000-0000-000000000006', $x$Glucagon's mechanism -- stimulating cardiac adenylate cyclase via a receptor distinct from the beta-adrenergic receptor -- allows it to increase heart rate and contractility despite ongoing beta-receptor blockade, making it the specific antidote for this toxicity.$x$, 1),
('fa000000-0000-0000-0000-000000000006', 'Catecholamines (e.g. adrenaline) have reduced efficacy in significant beta-blocker overdose precisely because their action depends on the beta-receptor that is pharmacologically blocked.', 2),
('fa000000-0000-0000-0000-000000000006', 'Severe beta-blocker toxicity causing bradycardia and hypotension is a medical emergency requiring prompt recognition and specific treatment, given the risk of cardiovascular collapse.', 3),
('fa000000-0000-0000-0000-000000000007', 'Reduced ability to safely swallow (from confusion/disorientation) is an indication for parenteral rather than oral hypoglycaemia treatment, given the aspiration risk.', 1),
('fa000000-0000-0000-0000-000000000007', 'IM glucagon is a practical option when IV access is not immediately available, working by stimulating hepatic glycogen breakdown to raise blood glucose.', 2),
('fa000000-0000-0000-0000-000000000007', 'Once glucose has been corrected and she is able to swallow safely, oral carbohydrate should be given to maintain glucose levels and prevent recurrence, alongside review of her insulin regimen and any precipitating cause.', 3),
('fa000000-0000-0000-0000-000000000008', 'Tinnitus with a mixed respiratory alkalosis (from direct respiratory centre stimulation) and metabolic acidosis (from accumulating organic acids and uncoupling of oxidative phosphorylation) is the classic acid-base pattern of salicylate-type toxicity.', 1),
('fa000000-0000-0000-0000-000000000008', 'Activated charcoal can reduce absorption if given within an appropriate time window after a significant acute ingestion, forming part of initial management alongside supportive care.', 2),
('fa000000-0000-0000-0000-000000000008', 'Assessing and monitoring the severity of any significant analgesic overdose (including co-ingestion screening, e.g. for paracetamol) and acid-base status guides the need for further specific interventions such as urinary alkalinisation or dialysis in severe cases.', 3),
('fa000000-0000-0000-0000-000000000009', 'Ethylene glycol itself is relatively non-toxic, but its metabolism via alcohol dehydrogenase produces toxic metabolites responsible for the severe metabolic acidosis and end-organ damage seen in significant poisoning.', 1),
('fa000000-0000-0000-0000-000000000009', 'Fomepizole competitively and specifically inhibits alcohol dehydrogenase, halting toxic metabolite formation, and is preferred over ethanol therapy where available due to a more predictable dosing profile and fewer side effects.', 2),
('fa000000-0000-0000-0000-000000000009', 'Severe cases with significant acidosis, renal impairment or very high levels may also require haemodialysis to remove both the parent compound and toxic metabolites, alongside alcohol dehydrogenase inhibition.', 3),
('fa000000-0000-0000-0000-000000000010', 'The threshold and specific reversal approach for an elevated INR depends on both the degree of elevation and the presence or absence of bleeding, reflecting a graded management approach rather than a single uniform response.', 1),
('fa000000-0000-0000-0000-000000000010', 'Oral (rather than IV) vitamin K is generally used for significant elevation without bleeding, providing a more gradual, appropriately-paced correction than the rapid reversal needed for active major bleeding.', 2),
('fa000000-0000-0000-0000-000000000010', 'Warfarin is typically restarted at a lower dose once the INR has returned to a safer range, alongside review of any factors that may have contributed to the over-anticoagulation.', 3),
('fa000000-0000-0000-0000-000000000011', 'Major or life-threatening bleeding on warfarin requires the most rapid, complete reversal approach (IV vitamin K plus PCC), distinguishing management from the more conservative approach used for an elevated INR without bleeding.', 1),
('fa000000-0000-0000-0000-000000000011', 'PCC provides immediate replacement of the vitamin K-dependent clotting factors depleted by warfarin, correcting the coagulopathy far more rapidly than vitamin K alone, which takes hours to take full effect via new factor synthesis.', 2),
('fa000000-0000-0000-0000-000000000011', 'A mechanical heart valve is an important consideration in ongoing management, as anticoagulation will generally need to be carefully reintroduced once bleeding is controlled, given the significant thrombotic risk of the valve itself if anticoagulation is stopped for a prolonged period.', 3),
('fa000000-0000-0000-0000-000000000012', 'Different direct oral anticoagulants require different specific reversal agents depending on their mechanism of action (direct thrombin inhibition versus factor Xa inhibition), making correct identification of the specific drug essential.', 1),
('fa000000-0000-0000-0000-000000000012', 'Andexanet alfa works as a decoy substrate, binding factor Xa inhibitors and restoring normal endogenous factor Xa activity, distinguishing its mechanism from the factor-replacement approach of PCC.', 2),
('fa000000-0000-0000-0000-000000000012', 'In emergency settings where the specific reversal agent is unavailable, PCC is used as a less targeted but still clinically useful alternative for factor Xa inhibitor-associated major bleeding.', 3),
('fa000000-0000-0000-0000-000000000013', 'Idarucizumab specifically and rapidly neutralises dabigatran through direct, high-affinity antibody fragment binding, distinguishing its precise mechanism from the broader factor-replacement approach of PCC.', 1),
('fa000000-0000-0000-0000-000000000013', 'Correctly distinguishing between direct thrombin inhibitors (dabigatran, requiring idarucizumab) and factor Xa inhibitors (rivaroxaban/apixaban, requiring andexanet alfa) is essential for selecting the appropriate specific reversal agent in an emergency.', 2),
('fa000000-0000-0000-0000-000000000013', $x$Idarucizumab's rapid, complete reversal makes it particularly valuable in scenarios requiring urgent surgical or procedural intervention, such as this case of intracranial haemorrhage needing neurosurgery.$x$, 3),
('fa000000-0000-0000-0000-000000000014', $x$Aspirin's cyclooxygenase inhibition and P2Y12 inhibitors' ADP receptor blockade represent distinct, complementary mechanisms of platelet inhibition, explaining the enhanced antithrombotic effect of combining them.$x$, 1),
('fa000000-0000-0000-0000-000000000014', 'Stent thrombosis is a serious, potentially fatal complication, particularly relevant during the period before the stent has fully endothelialised, providing the clinical rationale for dual antiplatelet therapy during this higher-risk window.', 2),
('fa000000-0000-0000-0000-000000000014', 'The duration of dual antiplatelet therapy balances the reduced stent thrombosis risk against the increased bleeding risk of combination therapy, individualised based on stent type, clinical presentation, and bleeding risk factors.', 3),
('fa000000-0000-0000-0000-000000000015', $x$Unfractionated heparin's variable binding to plasma proteins and endothelial cells contributes to its unpredictable dose-response relationship, distinguishing its monitoring requirements from the more predictable LMWH.$x$, 1),
('fa000000-0000-0000-0000-000000000015', 'APTT is titrated to a target therapeutic range to balance adequate anticoagulation (preventing clot extension/recurrence) against excessive anticoagulation (bleeding risk).', 2),
('fa000000-0000-0000-0000-000000000015', 'This monitoring requirement is a practical consideration when choosing between unfractionated and low molecular weight heparin, alongside factors such as renal function (UFH being preferred in severe renal impairment given its non-renal clearance) and need for rapid reversibility.', 3),
('fa000000-0000-0000-0000-000000000016', 'HIT typically develops 5-10 days after starting heparin (or more rapidly with prior heparin exposure), the classic temporal pattern justifying scheduled platelet count monitoring during this period.', 1),
('fa000000-0000-0000-0000-000000000016', 'The paradoxical association between falling platelet count and increased (not decreased) thrombotic risk is a distinguishing, clinically critical feature of HIT compared with other causes of drug-induced thrombocytopenia.', 2),
('fa000000-0000-0000-0000-000000000016', 'If HIT is identified or strongly suspected, heparin must be stopped immediately and a non-heparin anticoagulant substituted, given the significant risk of severe thrombotic complications if heparin is continued.', 3),
('fa000000-0000-0000-0000-000000000017', 'Bleeding risk scores are primarily used to identify and address modifiable risk factors, rather than as a standalone tool to exclude patients from anticoagulation, an important distinction in their intended clinical use.', 1),
('fa000000-0000-0000-0000-000000000017', 'The decision to anticoagulate weighs bleeding risk against thromboembolic (stroke) risk together, recognising that stroke prevention benefit frequently outweighs bleeding risk even in patients with several bleeding risk factors.', 2),
('fa000000-0000-0000-0000-000000000017', $x$Addressing modifiable factors (blood pressure control, reviewing concurrent antiplatelet/NSAID use, falls risk assessment and intervention) can meaningfully reduce bleeding risk over time, supporting a more nuanced, individualised approach rather than a binary treat/don't-treat decision based on a single score.$x$, 3),
('fa000000-0000-0000-0000-000000000018', 'An eGFR below 30 mL/min/1.73m2 is the accepted threshold at which metformin must not be started (or must be stopped if already in use), due to accumulation and lactic acidosis risk.', 1),
('fa000000-0000-0000-0000-000000000018', 'Between eGFR 30-45, dose reduction (rather than complete avoidance) is the standard approach, distinguishing this less severe impairment range from the more significant impairment described here.', 2),
('fa000000-0000-0000-0000-000000000018', $x$Metformin's renal clearance mechanism directly explains why declining renal function proportionately increases plasma drug levels and associated toxicity risk.$x$, 3),
('fa000000-0000-0000-0000-000000000019', 'Aminoglycosides (gentamicin, amikacin) are renally cleared with a narrow therapeutic index, making dose/interval adjustment in renal impairment essential to avoid toxicity while maintaining efficacy.', 1),
('fa000000-0000-0000-0000-000000000019', 'Therapeutic drug monitoring (measuring trough and/or peak levels) allows individualised dosing, particularly important in significant renal impairment where accumulation risk is high.', 2),
('fa000000-0000-0000-0000-000000000019', 'Nephrotoxicity from aminoglycosides can further worsen renal function, creating a risk of a worsening cycle if dosing is not carefully monitored and adjusted in this population.', 3),
('fa000000-0000-0000-0000-000000000020', 'Significant hepatic impairment can reduce the metabolism and clearance of many opioids, increasing the risk of drug accumulation and toxicity (sedation, respiratory depression, and precipitation of hepatic encephalopathy).', 1),
('fa000000-0000-0000-0000-000000000020', 'Lower starting doses with careful, cautious titration and close monitoring are the standard approach to opioid prescribing in significant hepatic impairment, rather than standard or increased dosing.', 2),
('fa000000-0000-0000-0000-000000000020', 'Specialist input (hepatology, palliative care, or pharmacy) is often valuable given the complexity of analgesic prescribing in advanced liver disease, balancing effective symptom control against toxicity risk.', 3),
('fa000000-0000-0000-0000-000000000021', 'Different DOACs have different degrees of renal dependence for clearance and different specific renal impairment thresholds/dose-adjustment criteria, meaning the approach cannot be generalised across the whole drug class without checking the specific agent.', 1),
('fa000000-0000-0000-0000-000000000021', $x$Apixaban's specific dose-reduction criteria (incorporating age, body weight and serum creatinine, alongside renal function assessment) reflect a more nuanced approach than a single eGFR cut-off alone.$x$, 2),
('fa000000-0000-0000-0000-000000000021', 'Regular renal function monitoring is recommended for patients on DOACs, particularly those with any degree of renal impairment or in older patients, given the potential for renal function to decline further over time, which could affect appropriate dosing.', 3),
('fa000000-0000-0000-0000-000000000022', 'NSAIDs impair renal prostaglandin-mediated compensatory vasodilation, a mechanism particularly problematic in cirrhosis, where renal perfusion is often already compromised by cirrhosis-related circulatory changes.', 1),
('fa000000-0000-0000-0000-000000000022', 'Worsened fluid retention from NSAID use can counteract diuretic therapy, complicating management of ascites in decompensated cirrhosis.', 2),
('fa000000-0000-0000-0000-000000000022', 'Increased gastrointestinal bleeding risk from NSAIDs is particularly concerning in cirrhosis, given the coexisting risk of oesophageal varices and any underlying coagulopathy from impaired hepatic synthetic function.', 3),
('fa000000-0000-0000-0000-000000000023', 'Statins remain an important secondary prevention therapy even in significant CKD, reflecting continued cardiovascular risk reduction benefit in this population.', 1),
('fa000000-0000-0000-0000-000000000023', 'Specific statins have varying degrees of renal elimination and different renal-related dosing considerations, meaning the approach should be tailored to the individual agent chosen rather than a blanket rule.', 2),
('fa000000-0000-0000-0000-000000000023', 'Balancing continued cardiovascular benefit against any specific renal-related prescribing caution reflects the general principle of individualised risk-benefit assessment in complex, multi-morbid patients.', 3),
('fa000000-0000-0000-0000-000000000024', 'Reduced hepatic metabolism in significant liver disease can prolong and enhance the sedative effects of many drugs, compounding the direct risk of sedating medications worsening encephalopathy.', 1),
('fa000000-0000-0000-0000-000000000024', 'Sedating medications are a recognised, modifiable precipitant of hepatic encephalopathy, alongside other factors such as infection, gastrointestinal bleeding, constipation and electrolyte disturbance, that should be actively reviewed for and addressed.', 2),
('fa000000-0000-0000-0000-000000000024', 'Identifying alternative, non-sedating management approaches for the underlying symptom (here, cholestatic pruritus) is an important part of safe prescribing in patients with or at risk of hepatic encephalopathy.', 3),
('fa000000-0000-0000-0000-000000000025', $x$Digoxin's predominantly renal route of elimination means declining renal function directly and significantly increases plasma drug levels at a given dose, unlike drugs with predominantly hepatic clearance.$x$, 1),
('fa000000-0000-0000-0000-000000000025', $x$Digoxin toxicity has a relatively narrow therapeutic window, and its risk is increased by both renal impairment (reduced clearance) and hypokalaemia (increased cardiac sensitivity to digoxin's effects), both relevant considerations in this population.$x$, 2),
('fa000000-0000-0000-0000-000000000025', $x$Digoxin level monitoring should always be interpreted alongside the patient's clinical picture and electrolytes, rather than as an isolated number, given that toxicity can occur even within the 'therapeutic' range in the presence of other risk factors such as hypokalaemia.$x$, 3),
('fa000000-0000-0000-0000-000000000026', 'Zero-order kinetics means a constant amount of drug is eliminated per unit time (regardless of concentration), unlike first-order kinetics, where a constant proportion is eliminated, explaining the disproportionate rise in levels with dose increases once saturation occurs.', 1),
('fa000000-0000-0000-0000-000000000026', 'Phenytoin is a classic example of a drug exhibiting this saturation phenomenon within the clinically relevant dose range, making small dose adjustments and careful level monitoring particularly important.', 2),
('fa000000-0000-0000-0000-000000000026', 'This unpredictable dose-concentration relationship is a key reason why phenytoin requires therapeutic drug monitoring and cautious, small dose increments when titrating therapy.', 3),
('fa000000-0000-0000-0000-000000000027', 'Volume of distribution describes the theoretical volume a drug would need to occupy to account for the total amount in the body at the concentration measured in plasma, reflecting the extent of tissue distribution.', 1),
('fa000000-0000-0000-0000-000000000027', 'Drugs with a small volume of distribution (remaining largely within plasma/extracellular fluid) are generally more amenable to removal by dialysis than those with a large volume of distribution.', 2),
('fa000000-0000-0000-0000-000000000027', 'This principle is clinically relevant when considering dialysis as a treatment option in significant drug overdose, helping predict which poisonings are likely to benefit from this intervention.', 3),
('fa000000-0000-0000-0000-000000000028', $x$The four-to-five half-life rule for reaching steady state is a fundamental, broadly applicable pharmacokinetic principle relevant to predicting when a drug's effect (and monitoring, e.g. therapeutic drug levels) will become stable and interpretable.$x$, 1),
('fa000000-0000-0000-0000-000000000028', 'This concept explains why loading doses are sometimes used clinically -- to achieve a therapeutic concentration more rapidly than waiting the several half-lives otherwise required to reach steady state through regular maintenance dosing alone.', 2),
('fa000000-0000-0000-0000-000000000028', 'Understanding this principle is also relevant when a dose is changed: a new steady state will similarly take four to five half-lives to be reached following the adjustment, informing appropriate timing for reassessment or level monitoring.', 3),
('fa000000-0000-0000-0000-000000000029', 'The relationship between loading dose, target concentration and volume of distribution allows calculation of an appropriate initial dose to rapidly achieve a therapeutic level.', 1),
('fa000000-0000-0000-0000-000000000029', 'This strategy is particularly valuable for drugs with a long half-life and in clinical situations (such as severe infection) where rapid attainment of effective drug levels is clinically important.', 2),
('fa000000-0000-0000-0000-000000000029', 'After the loading dose, regular maintenance dosing (calculated based on clearance) is used to sustain the achieved therapeutic concentration over time.', 3),
('fa000000-0000-0000-0000-000000000030', 'First-pass metabolism specifically relates to the oral (or other portal-circulation) route, explaining why oral bioavailability is often lower than intravenous bioavailability (which is, by definition, 100%) for drugs undergoing significant hepatic extraction.', 1),
('fa000000-0000-0000-0000-000000000030', 'Drugs with high first-pass metabolism may require substantially higher oral doses than intravenous doses to achieve equivalent systemic effect, or may not be suitable for oral administration at all in some cases.', 2),
('fa000000-0000-0000-0000-000000000030', 'Liver disease can significantly alter first-pass metabolism, potentially increasing the systemic bioavailability of affected drugs, an important consideration in hepatic impairment prescribing.', 3),
('fa000000-0000-0000-0000-000000000031', 'Clopidogrel is a prodrug, meaning it requires metabolic conversion (via CYP2C19) to an active form to exert its antiplatelet effect, distinguishing it from drugs that are pharmacologically active in their administered form.', 1),
('fa000000-0000-0000-0000-000000000031', 'CYP2C19 poor metaboliser status is a recognised, clinically significant pharmacogenomic variant affecting clopidogrel efficacy, illustrating the growing relevance of pharmacogenomic testing to personalised prescribing decisions.', 2),
('fa000000-0000-0000-0000-000000000031', 'Alternative antiplatelet agents (ticagrelor, prasugrel) do not depend on this same activation pathway, providing an option to consider in patients identified as CYP2C19 poor metabolisers who require effective antiplatelet therapy.', 3),
('fa000000-0000-0000-0000-000000000032', 'Only the free (unbound) fraction of a drug is pharmacologically active and available to cross membranes and exert its effect (or produce toxicity); protein binding effectively acts as a reservoir, releasing free drug as needed to maintain the free concentration.', 1),
('fa000000-0000-0000-0000-000000000032', 'Hypoalbuminaemia specifically affects highly protein-bound drugs, with less clinically significant impact on drugs with low protein binding, making this an important, drug-specific consideration.', 2),
('fa000000-0000-0000-0000-000000000032', 'Awareness of this phenomenon is important for correctly interpreting standard total drug level results in hypoalbuminaemic patients, sometimes requiring specific correction formulas or free drug level measurement for accurate clinical interpretation.', 3),
('fa000000-0000-0000-0000-000000000033', 'Multiple physiological changes occur with normal ageing (reduced hepatic blood flow/enzyme activity, reduced renal function, altered body composition affecting fat/water distribution and thus volume of distribution for different drug types) collectively affecting pharmacokinetics.', 1),
('fa000000-0000-0000-0000-000000000033', $x$Increased pharmacodynamic sensitivity to many drugs (e.g. increased sedative or hypotensive effects) often compounds these pharmacokinetic changes in older adults, reinforcing the 'start low, go slow' prescribing principle.$x$, 2),
('fa000000-0000-0000-0000-000000000033', $x$This general principle applies broadly across many drug classes in older adults, though the specific degree of caution needed still depends on the individual drug's properties and the patient's specific comorbidities and organ function.$x$, 3),
('fa000000-0000-0000-0000-000000000034', 'The absence of urticaria alongside angioedema is a useful clinical clue pointing towards a bradykinin-mediated (e.g. ACE inhibitor-related or hereditary angioedema) rather than an allergic, mast-cell/IgE-mediated cause.', 1),
('fa000000-0000-0000-0000-000000000034', 'ACE inhibitor angioedema can occur at any time during treatment, including after months or years of prior uneventful use, meaning a long treatment history does not exclude this diagnosis when a compatible presentation occurs.', 2),
('fa000000-0000-0000-0000-000000000034', 'Management requires immediate ACE inhibitor withdrawal (with avoidance of the entire class going forward, given cross-reactivity) and airway assessment/support, as standard allergy treatments (antihistamines, adrenaline, steroids) are less reliably effective given the non-allergic mechanism.', 3),
('fa000000-0000-0000-0000-000000000035', 'Methotrexate toxicity causing bone marrow suppression can present with mouth ulcers, sore throat and other infective symptoms, reflecting both direct mucosal toxicity and the consequences of neutropenia.', 1),
('fa000000-0000-0000-0000-000000000035', 'Any patient on methotrexate presenting with signs of infection or unwell state should have an urgent full blood count checked, given the risk of significant, potentially life-threatening bone marrow suppression.', 2),
('fa000000-0000-0000-0000-000000000035', 'Folic acid supplementation is used to reduce (but not eliminate) the risk of methotrexate-related mucosal and haematological toxicity, and other risk factors (renal impairment, drug interactions, dosing errors) should be reviewed when this toxicity occurs.', 3),
('fa000000-0000-0000-0000-000000000036', 'Neuroleptic malignant syndrome classically develops within the first two weeks of starting or increasing the dose of an antipsychotic (particularly first-generation/typical agents, though it can occur with any antipsychotic), an important temporal clue.', 1),
('fa000000-0000-0000-0000-000000000036', $x$The tetrad of hyperthermia, severe rigidity ('lead-pipe' rigidity), autonomic instability and altered mental state, alongside markedly elevated creatine kinase (reflecting muscle breakdown), together distinguish this from other causes of fever or rigidity in a psychiatric patient.$x$, 2),
('fa000000-0000-0000-0000-000000000036', 'Immediate cessation of the causative antipsychotic, along with supportive care and monitoring for complications (particularly acute kidney injury from rhabdomyolysis), is essential given the significant mortality risk if unrecognised or untreated.', 3),
('fa000000-0000-0000-0000-000000000037', 'Hydroxychloroquine retinopathy risk increases with cumulative dose and duration of treatment, meaning risk (and screening frequency) is influenced by how long a patient has been on treatment and their total dose, not simply current dose alone.', 1),
('fa000000-0000-0000-0000-000000000037', 'Early retinopathy can be asymptomatic, making structured screening (rather than waiting for symptoms to develop) important for detecting toxicity before irreversible visual damage occurs.', 2),
('fa000000-0000-0000-0000-000000000037', 'This represents an example of a type C (chronic, cumulative-exposure-related) adverse drug reaction, distinguishing its mechanism and monitoring approach from acute, dose-related type A reactions.', 3),
('fa000000-0000-0000-0000-000000000038', 'Isoniazid interferes with pyridoxine metabolism, and patients with additional risk factors for neuropathy (diabetes, chronic alcohol excess, malnutrition, HIV, pregnancy) are at particularly increased risk, often prompting routine prophylactic co-prescription in these groups.', 1),
('fa000000-0000-0000-0000-000000000038', 'Isoniazid-associated hepatotoxicity is managed separately, through baseline and ongoing liver function monitoring and patient education about symptoms of liver injury, rather than through pyridoxine supplementation.', 2),
('fa000000-0000-0000-0000-000000000038', 'This is an example of a well-established, evidence-based strategy to mitigate a specific, recognised type A adverse drug reaction through a simple, low-risk co-prescribed supplement.', 3),
('fa000000-0000-0000-0000-000000000039', $x$Amiodarone's structural similarity to thyroxine (containing iodine) underlies its potential to cause both hypothyroidism (via a Wolff-Chaikoff-type effect) and hyperthyroidism (via excess iodine-driven thyroid hormone synthesis or direct thyroiditis), requiring regular thyroid function monitoring.$x$, 1),
('fa000000-0000-0000-0000-000000000039', $x$Amiodarone's very long half-life (often several weeks) means its effects, including toxicity, can persist or even emerge some time after the drug has been stopped, relevant both to monitoring duration and to interpreting new symptoms after discontinuation.$x$, 2),
('fa000000-0000-0000-0000-000000000039', 'Baseline assessment (thyroid function, liver function, and often chest X-ray/pulmonary function tests) before starting amiodarone, followed by regular structured monitoring during treatment, is the standard approach to enable early detection of these recognised toxicities.', 3),
('fa000000-0000-0000-0000-000000000040', 'Red man syndrome is specifically related to the rate of vancomycin infusion (more common with rapid infusion), distinguishing it as a preventable, infusion-technique-related reaction rather than a fixed drug allergy.', 1),
('fa000000-0000-0000-0000-000000000040', 'Differentiating red man syndrome from true IgE-mediated vancomycin allergy (or anaphylaxis) is clinically important, as it determines whether the drug can be safely continued (with a slower infusion rate) or must be avoided in future.', 2),
('fa000000-0000-0000-0000-000000000040', 'Premedication with an antihistamine and ensuring an appropriately slow infusion rate can help prevent recurrence in patients who have previously experienced this reaction and require ongoing vancomycin therapy.', 3),
('fa000000-0000-0000-0000-000000000041', 'The HLA-B*1502 allele is considerably more prevalent in individuals of Southeast Asian and Han Chinese ancestry, which is why targeted pre-treatment screening is specifically recommended in these populations before starting carbamazepine.', 1),
('fa000000-0000-0000-0000-000000000041', 'Stevens-Johnson syndrome and toxic epidermal necrolysis are severe, potentially life-threatening mucocutaneous reactions with significant morbidity and mortality, making pre-emptive genetic risk identification a valuable preventive strategy where feasible.', 2),
('fa000000-0000-0000-0000-000000000041', 'This represents a practical example of pharmacogenomic screening being used prospectively to guide drug selection and avoid a specific, serious, genetically-predisposed adverse drug reaction, rather than simply reacting to toxicity after it occurs.', 3),
('fa000000-0000-0000-0000-000000000042', 'Macrolide antibiotics (particularly erythromycin and clarithromycin, less so azithromycin) are well-recognised CYP450 inhibitors with numerous clinically significant drug interactions, including with warfarin.', 1),
('fa000000-0000-0000-0000-000000000042', 'Any new medication started in a patient on warfarin should prompt consideration of potential interactions, with closer INR monitoring arranged where an interacting drug cannot be avoided.', 2),
('fa000000-0000-0000-0000-000000000042', 'This case illustrates the importance of careful medication reconciliation across care settings (here, an out-of-hours service unaware of his regular warfarin), a recognised source of preventable drug interaction-related harm.', 3),
('fa000000-0000-0000-0000-000000000043', 'Enzyme-inducing anti-epileptic drugs (including carbamazepine, phenytoin and phenobarbital) reduce the efficacy of standard-dose combined and progestogen-only hormonal contraceptives, requiring specific contraceptive counselling and consideration of alternative or adjusted approaches.', 1),
('fa000000-0000-0000-0000-000000000043', 'This interaction is an important, practical example of enzyme induction (in contrast to enzyme inhibition, which increases rather than decreases co-administered drug levels), with a clinically significant real-world consequence.', 2),
('fa000000-0000-0000-0000-000000000043', 'Non-hormonally-interacting contraceptive methods (such as the intrauterine device) or specific dose/monitoring adjustments to hormonal methods should be discussed with patients on enzyme-inducing anti-epileptic drugs requiring effective contraception.', 3),
('fa000000-0000-0000-0000-000000000044', 'P-glycoprotein is an efflux transporter relevant to the clearance of several drugs, including digoxin; inhibition of this transporter by amiodarone (and several other drugs) reduces digoxin clearance and raises plasma levels.', 1),
('fa000000-0000-0000-0000-000000000044', $x$Digoxin's narrow therapeutic index means even a relatively modest interaction-related rise in plasma levels can precipitate clinically significant toxicity, justifying proactive dose adjustment rather than waiting for toxicity to develop.$x$, 2),
('fa000000-0000-0000-0000-000000000044', 'Digoxin level monitoring after starting amiodarone (or any other interacting drug) helps confirm that dose adjustment has achieved an appropriate, safe therapeutic level.', 3),
('fa000000-0000-0000-0000-000000000045', $x$Tramadol's dual mechanism (opioid receptor activity plus serotonin and noradrenaline reuptake inhibition) distinguishes it from most other opioids in its potential to precipitate serotonin syndrome when combined with other serotonergic drugs.$x$, 1),
('fa000000-0000-0000-0000-000000000045', 'Hyperreflexia and clonus are relatively specific clinical features helping distinguish serotonin syndrome from other causes of agitation and autonomic disturbance, such as neuroleptic malignant syndrome (more associated with rigidity) or anticholinergic toxicity.', 2),
('fa000000-0000-0000-0000-000000000045', 'Prescribers across different specialties (here, a surgical team) should always check for interacting serotonergic medications before prescribing tramadol or other serotonergic drugs, reinforcing the importance of medication reconciliation across care transitions.', 3),
('fa000000-0000-0000-0000-000000000046', $x$The 'triple whammy' (ACE inhibitor/ARB plus NSAID plus diuretic, particularly potassium-sparing) is a well-recognised, clinically important combination increasing acute kidney injury and hyperkalaemia risk, relevant to prescribing safety education and medication review.$x$, 1),
('fa000000-0000-0000-0000-000000000046', 'NSAIDs reduce prostaglandin-mediated afferent arteriolar vasodilation, which is particularly important for maintaining glomerular filtration when renal perfusion is already compromised (e.g. by ACE inhibitor-related efferent arteriolar dilation), explaining the renal function risk of this combination.', 2),
('fa000000-0000-0000-0000-000000000046', 'This hyperkalaemia (6.4 mmol/L) requires urgent assessment (including ECG for hyperkalaemia-related changes) and treatment, alongside medication review, given the risk of life-threatening arrhythmia.', 3),
('fa000000-0000-0000-0000-000000000047', 'Not all statins share the same degree of CYP3A4 dependence; simvastatin and atorvastatin are particularly affected by CYP3A4 inhibitors, whereas statins such as rosuvastatin and pravastatin have less CYP3A4-dependent metabolism and may be safer alternatives when a significant interacting drug is needed.', 1),
('fa000000-0000-0000-0000-000000000047', 'Macrolide antibiotics (particularly clarithromycin and erythromycin) are well-recognised potent CYP3A4 inhibitors, relevant to numerous clinically significant drug interactions beyond just this statin example.', 2),
('fa000000-0000-0000-0000-000000000047', 'Prompt recognition and action (stopping the interacting statin, checking creatine kinase and renal function, considering an alternative statin or antibiotic) are important given the risk of progression to severe rhabdomyolysis with associated acute kidney injury if the interaction is not addressed.', 3),
('fa000000-0000-0000-0000-000000000048', 'The breadth and potency of protease inhibitor-related interactions make specialist input (HIV pharmacy/pharmacology) and use of dedicated interaction-checking resources particularly valuable whenever new medications are considered in patients on these regimens.', 1),
('fa000000-0000-0000-0000-000000000048', 'Some interactions with protease inhibitors are severe enough to be absolutely contraindicated combinations (e.g. with certain statins or ergot alkaloids), rather than simply requiring dose adjustment or monitoring, reflecting the importance of proactive rather than reactive interaction management.', 2),
('fa000000-0000-0000-0000-000000000048', 'This scenario illustrates a broader principle: certain drug classes (potent enzyme inhibitors/inducers with broad substrate specificity) warrant a specifically heightened index of suspicion for interactions whenever any new co-prescription is considered.', 3),
('fa000000-0000-0000-0000-000000000049', 'Lithium is handled similarly to sodium at the proximal renal tubule, explaining why factors affecting proximal sodium reabsorption (such as thiazide-induced volume depletion) directly affect lithium clearance and levels.', 1),
('fa000000-0000-0000-0000-000000000049', 'Any new medication affecting renal function or fluid/electrolyte balance (including diuretics, ACE inhibitors/ARBs, and NSAIDs) should prompt consideration of potential effects on lithium levels in patients established on lithium therapy.', 2),
('fa000000-0000-0000-0000-000000000049', 'Closer lithium level monitoring (and clinical review for early toxicity symptoms) is recommended when an interacting drug cannot be avoided, allowing early detection and dose adjustment before significant toxicity develops.', 3),
('fa000000-0000-0000-0000-000000000050', 'This interaction illustrates a pharmacodynamic (rather than purely pharmacokinetic) mechanism: two drugs acting on the same pathway (folate metabolism) produce an additive, clinically dangerous combined effect.', 1),
('fa000000-0000-0000-0000-000000000050', $x$Folinic acid ('rescue') can be used to treat severe methotrexate-related toxicity by replenishing the folate pathway downstream of the blocked enzyme, though the priority in this interaction is avoidance through careful prescribing rather than relying on rescue treatment after toxicity develops.$x$, 2),
('fa000000-0000-0000-0000-000000000050', 'This case reinforces the importance of medication reconciliation across care settings (here, an out-of-hours service unaware of his regular methotrexate), a recurring theme in preventable, interaction-related adverse drug reactions.', 3);
